(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("callimachus-hymns-e", [{"sp": "HDR", "t": "Ὕμνοι καὶ Ἐπιγράμματα"}, {"sp": "SEC", "t": "Εἰς Δία", "st": "H1"}, {"sp": "N", "t": "Ζηνὸς ἔοι τί κεν ἄλλο παρὰ σπονδῆισιν ἀείδειν<br>λώιον ἢ θεὸν αὐτόν, ἀεὶ μέγαν, αἰὲν ἄνακτα,<br>Πηλαγόνων ἐλατῆρα, δικασπόλον οὐρανίδηισι;", "st": "H1"}, {"sp": "N", "t": "πῶς καί μιν, Δικταῖον ἀείσομεν ἠὲ Λυκαῖον;<br>ἐν δοιῆι μάλα θυμός, ἐπεὶ γένος ἀμφήριστον.<br>Ζεῦ σὲ μὲν Ἰδαίοισιν ἐν οὔρεσί φασι γενέσθαι,<br>Ζεῦ σὲ δ’ ἐν Ἀρκαδίηι· πότεροι, πάτερ, ἐψεύσαντο;<br>‘Κρῆτες ἀεὶ ψεῦσται’· καὶ γὰρ τάφον, ὦ ἄνα, σεῖο<br>Κρῆτες ἐτεκτήναντο· σὺ δ’ οὐ θάνες, ἐσσὶ γὰρ αἰεί.<br>ἐν δέ σε Παρρασίηι Ῥείη τέκεν, ἧχι μάλιστα<br>ἔσκεν ὄρος θάμνοισι περισκεπές (ἔνθεν ὁ χῶρος<br>ἱερός, οὐδέ τί μιν κεχρημένον Εἰλειθυίης<br>ἑρπετὸν οὐδὲ γυνὴ ἐπιμίσγεται, ἀλλά ἑ Ῥείης<br>ὠγύγιον καλέουσι λεχώιον Ἀπιδανῆες)·<br>ἔνθα σ’ ἐπεὶ μήτηρ μεγάλων ἀπεθήκατο κόλπων,<br>αὐτίκα δίζητο ῥόον ὕδατος ὧι κε τόκοιο<br>λύματα χυτλώσαιτο τεὸν δ’ ἐνὶ χρῶτα λοέσσαι.", "st": "H1"}, {"sp": "N", "t": "Λάδων ἀλλ’ οὔπω μέγας ἔρρεεν οὐδ’ Ἐρύμανθος,<br>λευκότατος ποταμῶν, ἔτι δ’ ἄβροχος ἦεν ἅπασα<br>Ἀρκαδίη· μέλλεν δὲ μάλ’ εὔυδρος καλέεσθαι<br>αὖτις· ἐπεὶ τημόσδε, Ῥέη ὅτ’ ἐλύσατο μίτρην,<br>ἦ πολλὰς ἐφύπερθε σαρωνίδας ὑγρὸς Ἰάων<br>ἤειρεν, πολλὰς δὲ Μέλας ὤκχησεν ἁμάξας,<br>πολλὰ δὲ Καρίωνος ἄνω διεροῦ περ ἐόντος<br>ἰλυοὺς ἐβάλοντο κινώπετα, νίσσετο δ’ ἀνήρ<br>πεζὸς ὑπὲρ Κρᾶθίν τε πολύστιόν τε Μετώπην<br>διψαλέος· τὸ δὲ πολλὸν ὕδωρ ὑπὸ ποσσὶν ἔκειτο.<br>καί ῥ’ ὑπ’ ἀμηχανίης σχομένη φάτο πότνια Ῥείη<br>‘Γαῖα φίλη τέκε καὶ σύ· τεαὶ δ’ ὠδῖνες ἐλαφραί.’<br>εἶπε καὶ ἀντανύσασα θεὴ μέγαν ὑψόθι πῆχυν<br>πλῆξεν ὄρος σκήπτρωι· τὸ δέ οἱ δίχα πουλὺ διέστη,<br>ἐκ δ’ ἔχεεν μέγα χεῦμα· τόθι χρόα φαιδρύνασα<br>ὦνα τεὸν σπείρωσε, Νέδηι δέ σε δῶκε κομίζειν<br>κευθμὸν ἔσω Κρηταῖον, ἵνα κρύφα παιδεύοιο,<br>πρεσβυτάτηι Νυμφέων, αἵ μιν τότε μαιώσαντο<br>πρωτίστη γενεὴ μετά γε Στύγα τε Φιλύρην τε.", "st": "H1"}, {"sp": "N", "t": "οὐδ’ ἁλίην ἀπέτεισε θεὴ χάριν, ἀλλὰ τὸ χεῦμα<br>κεῖνο Νέδην ὀνόμηνε· τὸ μέν ποθι πουλὺ κατ’ αὐτό<br>Καυκώνων πτολίεθρον, ὃ Λέπρειον πεφάτισται,<br>συμφέρεται Νηρῆι, παλαιότατον δέ μιν ὕδωρ<br>υἱωνοὶ πίνουσι Λυκαονίης ἄρκτοιο.<br>εὖτε Θενὰς ἀπέλειπεν ἐπὶ Κνωσοῖο φέρουσα<br>Ζεῦ πάτερ ἡ Νύμφη σε (Θεναὶ δ’ ἔσαν ἐγγύθι Κνωσοῦ),<br>τουτάκι τοι πέσε δαῖμον ἄπ’ ὀμφαλός· ἔνθεν ἐκεῖνο<br>ὀμφάλιον μετέπειτα πέδον καλέουσι Κύδωνες.<br>Ζεῦ σὲ δὲ Κυρβάντων ἑτάραι προσεπηχύναντο<br>Δικταῖαι Μελίαι, σὲ δ’ ἐκοίμισεν Ἀδρήστεια<br>λίκνωι ἐνὶ χρυσέωι, σὺ δ’ ἐθήσαο πίονα μαζόν<br>αἰγὸς Ἀμαλθείης, ἐπὶ δὲ γλυκὺ κηρίον ἔβρως.<br>γέντο γὰρ ἐξαπιναῖα Πανακρίδος ἔργα μελίσσης<br>Ἰδαίοις ἐν ὄρεσσι, τά τε κλείουσι Πάνακρα.<br>οὖλα δὲ Κούρητές σε περὶ πρύλιν ὠρχήσαντο<br>τεύχεα πεπλήγοντες, ἵνα Κρόνος οὔασιν ἠχήν<br>ἀσπίδος εἰσαΐοι καὶ μή σεο κουρίζοντος.", "st": "H1"}, {"sp": "N", "t": "καλὰ μὲν ἠέξευ, καλὰ δ’ ἔτραφες οὐράνιε Ζεῦ,<br>ὀξὺ δ’ ἀνήβησας, ταχινοὶ δέ τοι ἦλθον ἴουλοι.<br>ἀλλ’ ἔτι παιδνὸς ἐὼν ἐφράσσαο πάντα τέλεια·<br>τῶι τοι καὶ γνωτοὶ προτερηγενέες περ ἐόντες<br>οὐρανὸν οὐκ ἐμέγηραν ἔχειν ἐπιδαίσιον οἶκον.<br>δηναιοὶ δ’ οὐ πάμπαν ἀληθέες ἦσαν ἀοιδοί·<br>φάντο πάλον Κρονίδηισι διάτριχα δώματα νεῖμαι·<br>τίς δέ κ’ ἐπ’ οὐλύμπωι τε καὶ ἄιδι κλῆρον ἐρύσσαι,<br>ὃς μάλα μὴ νενίηλος; ἐπ’ ἰσαίηι γὰρ ἔοικε<br>πήλασθαι· τὰ δὲ τόσσον ὅσον διὰ πλεῖστον ἔχουσι.<br>ψευδοίμην ἀίοντος ἅ κεν πεπίθοιεν ἀκουήν.<br>οὔ σε θεῶν ἐσσῆνα πάλοι θέσαν, ἔργα δὲ χειρῶν,<br>σή τε βίη τό τε κάρτος, ὃ καὶ πέλας εἵσαο δίφρου.<br>θήκαο δ’ οἰωνῶν μέγ’ ὑπείροχον ἀγγελιώτην<br>σῶν τεράων· ἅ τ’ ἐμοῖσι φίλοις ἐνδέξια φαίνοις.", "st": "H1"}, {"sp": "N", "t": "εἵλεο δ’ αἰζηῶν ὅ τι φέρτατον· οὐ σύ γε νηῶν<br>ἐμπεράμους, οὐκ ἄνδρα σακέσπαλον, οὐ μὲν ἀοιδόν·<br>ἀλλὰ τὰ μὲν μακάρεσσιν ὀλίζοσιν αὖθι παρῆκας<br>ἄλλα μέλειν ἑτέροισι, σὺ δ’ ἐξέλεο πτολιάρχους<br>αὐτούς, ὧν ὑπὸ χεῖρα γεωμόρος, ὧν ἴδρις αἰχμῆς,<br>ὧν ἐρέτης, ὧν πάντα· τί δ’ οὐ κρατέοντος ὑπ’ ἰσχύν;<br>αὐτίκα χαλκῆας μὲν ὑδείομεν Ἡφαίστοιο,<br>τευχηστὰς δ’ Ἄρηος, ἐπακτῆρας δὲ Χιτώνης<br>Ἀρτέμιδος, Φοίβου δὲ λύρης εὖ εἰδότας οἴμους·<br>‘ἐκ δὲ Διὸς βασιλῆες’· ἐπὶ χθονὸς οὐδὲν ἀνάκτων<br>θειότερον· τῶι καί σφε τεὴν ἐκρίναο λάξιν.<br>δῶκας δὲ πτολίεθρα φυλασσέμεν, ἵζεο δ’ αὐτὸς<br>ἄκρηισ’ ἐν πολίεσσιν, ἐπόψιος οἵ τε δίκηισι<br>λαὸν ὑπὸ σκολιῆισ’ οἵ τ’ ἔμπαλιν ἰθύνουσιν·<br>ἐν δὲ ῥυηφενίην ἔβαλές σφισιν, ἐν δ’ ἅλις ὄλβον·<br>πᾶσι μέν, οὐ μάλα δ’ ἶσον. ἔοικε δὲ τεκμήρασθαι<br>ἡμετέρωι μεδέοντι· περιπρὸ γὰρ εὐρὺ βέβηκεν.<br>ἑσπέριος κεῖνός γε τελεῖ τά κεν ἦρι νοήσηι·<br>ἑσπέριος τὰ μέγιστα, τὰ μείονα δ’, εὖτε νοήσηι.<br>οἳ δὲ τὰ μὲν πλειῶνι, τὰ δ’ οὐχ ἑνί, τῶν δ’ ἀπὸ πάμπαν<br>αὐτὸς ἄνην ἐκόλουσας, ἐνέκλασσας δὲ μενοινήν.", "st": "H1"}, {"sp": "N", "t": "χαῖρε μέγα Κρονίδη πανυπέρτατε, δῶτορ ἐάων,<br>δῶτορ ἀπημονίης. τεὰ δ’ ἔργματα τίς κεν ἀείδοι;<br>οὐ γένετ’, οὐκ ἔσται· τίς καὶ Διὸς ἔργματ’ ἀείσει;<br>χαῖρε πάτερ, χαῖρ’ αὖθι· δίδου δ’ ἀρετήν τ’ ἄφενός τε.<br>οὔτ’ ἀρετῆς ἄτερ ὄλβος ἐπίσταται ἄνδρας ἀέξειν<br>οὔτ’ ἀρετὴ ἀφένοιο· δίδου δ’ ἀρετήν τε καὶ ὄλβον.", "st": "H1"}, {"sp": "SEC", "t": "Εἰς Ἀπόλλωνα", "st": "H2"}, {"sp": "N", "t": "οἷον ὁ τὠπόλλωνος ἐσείσατο δάφνινος ὅρπηξ,<br>οἷα δ’ ὅλον τὸ μέλαθρον· ἑκὰς ἑκὰς ὅστις ἀλιτρός.<br>καὶ δή που τὰ θύρετρα καλῶι ποδὶ Φοῖβος ἀράσσει·<br>οὐχ ὁράαις; ἐπένευσεν ὁ Δήλιος ἡδύ τι φοῖνιξ<br>ἐξαπίνης, ὁ δὲ κύκνος ἐν ἠέρι καλὸν ἀείδει.<br>αὐτοὶ νῦν κατοχῆες ἀνακλίνεσθε πυλάων,<br>αὐταὶ δὲ κληῖδες· ὁ γὰρ θεὸς οὐκ ἔτι μακρήν.<br>οἱ δὲ νέοι μολπήν τε καὶ ἐς χορὸν ἐντύνεσθε.<br>ὡπόλλων οὐ παντὶ φαείνεται, ἀλλ’ ὅ τις ἐσθλός·<br>ὅς μιν ἴδηι, μέγας οὗτος, ὃς οὐκ ἴδε, λιτὸς ἐκεῖνος.<br>ὀψόμεθ’, ὦ Ἑκάεργε, καὶ ἐσσόμεθ’ οὔποτε λιτοί.<br>μήτε σιωπηλὴν κίθαριν μήτ’ ἄψοφον ἴχνος<br>τοῦ Φοίβου τοὺς παῖδας ἔχειν ἐπιδημήσαντος,<br>εἰ τελέειν μέλλουσι γάμον πολιήν τε κερεῖσθαι,<br>ἑστήξειν δὲ τὸ τεῖχος ἐπ’ ἀρχαίοισι θεμέθλοις.<br>ἠγασάμην τοὺς παῖδας, ἐπεὶ χέλυς οὐκέτ’ ἀεργός.", "st": "H2"}, {"sp": "N", "t": "εὐφημεῖτ’ ἀίοντες ἐπ’ Ἀπόλλωνος ἀοιδῆι.<br>εὐφημεῖ καὶ πόντος, ὅτε κλείουσιν ἀοιδοί<br>ἢ κίθαριν ἢ τόξα, Λυκωρέος ἔντεα Φοίβου.<br>οὐδὲ Θέτις Ἀχιλῆα κινύρεται αἴλινα μήτηρ,<br>ὁππόθ’ ἱὴ παιῆον ἱὴ παιῆον ἀκούσηι.<br>καὶ μὲν ὁ δακρυόεις ἀναβάλλεται ἄλγεα πέτρος,<br>ὅστις ἐνὶ Φρυγίηι διερὸς λίθος ἐστήρικται,<br>μάρμαρον ἀντὶ γυναικὸς ὀιζυρόν τι χανούσης.<br>ἱὴ ἱὴ φθέγγεσθε· κακὸν μακάρεσσιν ἐρίζειν.<br>ὃς μάχεται μακάρεσσιν, ἐμῶι βασιλῆι μάχοιτο·<br>ὅστις ἐμῶι βασιλῆι, καὶ Ἀπόλλωνι μάχοιτο.<br>τὸν χορὸν ὡπόλλων, ὅ τι οἱ κατὰ θυμὸν ἀείδει,<br>τιμήσει· δύναται γάρ, ἐπεὶ Διὶ δεξιὸς ἧσται.<br>οὐδ’ ὁ χορὸς τὸν Φοῖβον ἐφ’ ἓν μόνον ἦμαρ ἀείσει,<br>ἔστι γὰρ εὔυμνος· τίς ἂν οὐ ῥέα Φοῖβον ἀείδοι;", "st": "H2"}, {"sp": "N", "t": "χρύσεα τὠπόλλωνι τό τ’ ἐνδυτὸν ἥ τ’ ἐπιπορπίς<br>ἥ τε λύρη τό τ’ ἄεμμα τὸ Λύκτιον ἥ τε φαρέτρη,<br>χρύσεα καὶ τὰ πέδιλα· πολύχρυσος γὰρ Ἀπόλλων.<br>καὶ δὲ πολυκτέανος· Πυθῶνί κε τεκμήραιο.<br>καὶ μὲν ἀεὶ καλὸς καὶ ἀεὶ νέος· οὔποτε Φοίβου<br>θηλείηισ’ οὐδ’ ὅσσον ἐπὶ χνόος ἦλθε παρειαῖς.<br>αἱ δὲ κόμαι θυόεντα πέδωι λείβουσιν ἔλαια.<br>οὐ λίπος Ἀπόλλωνος ἀποστάζουσιν ἔθειραι,<br>ἀλλ’ αὐτὴν πανάκειαν· ἐν ἄστεϊ δ’ ὦι κεν ἐκεῖναι<br>πρῶκες ἔραζε πέσωσιν ἀκήρια πάντ’ ἐγένοντο.", "st": "H2"}, {"sp": "N", "t": "τέχνηι δ’ ἀμφιλαφὴς οὔ τις τόσον ὅσσον Ἀπόλλων·<br>κεῖνος ὀιστευτὴν ἔλαχ’ ἀνέρα, κεῖνος ἀοιδόν<br>(Φοίβωι γὰρ καὶ τόξον ἐπιτρέπεται καὶ ἀοιδή),<br>κείνου δὲ θριαὶ καὶ μάντιες· ἐκ δέ νυ Φοίβου<br>ἰητροὶ δεδάασιν ἀνάβλησιν θανάτοιο.", "st": "H2"}, {"sp": "N", "t": "Φοῖβον καὶ Νόμιον κικλήσκομεν ἐξέτι κείνου,<br>ἐξότ’ ἐπ’ Ἀμφρυσσῶι ζευγίτιδας ἔτρεφεν ἵππους<br>ἠιθέου ὑπ’ ἔρωτι κεκαυμένος Ἀδμήτοιο.<br>ῥεῖά κε βουβόσιον τελέθοι πλέον, οὐδέ κεν αἶγες<br>δεύοιντο βρεφέων ἐπιμηλάδες ἧισιν Ἀπόλλων<br>βοσκομένηισ’ ὀφθαλμὸν ἐπήγαγεν· οὐδ’ ἀγάλακτες<br>οἴιες οὐδ’ ἄκυθοι, πᾶσαι δέ κεν εἶεν ὕπαρνοι,<br>ἡ δέ κε μουνοτόκος διδυμητόκος αἶψα γένοιτο.", "st": "H2"}, {"sp": "N", "t": "Φοίβωι δ’ ἑσπόμενοι πόλιας διεμετρήσαντο<br>ἄνθρωποι· Φοῖβος γὰρ ἀεὶ πολίεσσι φιληδεῖ<br>κτιζομένηισ’, αὐτὸς δὲ θεμείλια Φοῖβος ὑφαίνει.<br>τετραέτης τὰ πρῶτα θεμείλια Φοῖβος ἔπηξε<br>καλῆι ἐν Ὀρτυγίηι περιηγέος ἐγγύθι λίμνης.<br>Ἄρτεμις ἀγρώσσουσα καρήατα συνεχὲς αἰγῶν<br>Κυνθιάδων φορέεσκεν, ὃ δ’ ἔπλεκε βωμὸν Ἀπόλλων.<br>δείματο μὲν κεράεσσιν ἐδέθλια, πῆξε δὲ βωμὸν<br>ἐκ κεράων, κεραοὺς δὲ πέριξ ὑπεβάλλετο τοίχους.<br>ὧδ’ ἔμαθεν τὰ πρῶτα θεμείλια Φοῖβος ἐγείρειν.<br>Φοῖβος καὶ βαθύγειον ἐμὴν πόλιν ἔφρασε Βάττωι<br>καὶ Λιβύην ἐσιόντι κόραξ ἡγήσατο λαῶι<br>δεξιὸς οἰκιστῆρι καὶ ὤμοσε τείχεα δώσειν<br>ἡμετέροις βασιλεῦσιν· ἀεὶ δ’ εὔορκος Ἀπόλλων.<br>ὤπολλον, πολλοί σε Βοηδρόμιον καλέουσι,<br>πολλοὶ δὲ Κλάριον, πάντη δέ τοι οὔνομα πουλύ·<br>αὐτὰρ ἐγὼ Καρνεῖον· ἐμοὶ πατρώιον οὕτω.<br>Σπάρτη τοι Καρνεῖε τὸ δὴ πρώτιστον ἔδεθλον,<br>δεύτερον αὖ Θήρη, τρίτατόν γε μὲν ἄστυ Κυρήνης.", "st": "H2"}, {"sp": "N", "t": "ἐκ μέν σε Σπάρτης ἕκτον γένος Οἰδιπόδαο<br>ἤγαγε Θηραίην ἐς ἀπόκτισιν· ἐκ δέ σε Θήρης<br>οὖλος Ἀριστοτέλης Ἀσβυστίδι πάρθετο γαίηι,<br>δεῖμε δέ τοι μάλα καλὸν ἀνάκτορον, ἐν δὲ πόληι<br>θῆκε τελεσφορίην ἐπετήσιον, ἧι ἐνὶ πολλοί<br>ὑστάτιον πίπτουσιν ἐπ’ ἰσχίον, ὦ ἄνα, ταῦροι.<br>ἱὴ ἱὴ Καρνεῖε πολύλλιτε, σεῖο δὲ βωμοί<br>ἄνθεα μὲν φορέουσιν ἐν εἴαρι τόσσα περ Ὧραι<br>ποικίλ’ ἀγινεῦσι ζεφύρου πνείοντος ἐέρσην,<br>χείματι δὲ κρόκον ἡδύν· ἀεὶ δέ τοι ἀέναον πῦρ,<br>οὐδέ ποτε χθιζὸν περιβόσκεται ἄνθρακα τέφρη.<br>ἦ ῥ’ ἐχάρη μέγα Φοῖβος, ὅτε ζωστῆρες Ἐνυοῦς<br>ἀνέρες ὠρχήσαντο μετὰ ξανθῆισι Λιβύσσαις,<br>τέθμιαι εὖτέ σφιν Καρνειάδες ἤλυθον ὧραι.<br>οἳ δ’ οὔπω πηγῆισι Κύρης ἐδύναντο πελάσσαι<br>Δωριέες, πυκινὴν δὲ νάπαις Ἄζιλιν ἔναιον.<br>τοὺς μὲν ἄναξ ἴδεν αὐτός, ἑῆι δ’ ἐπεδείξατο νύμφηι<br>στὰς ἐπὶ Μυρτούσσης κερατώδεος, ἧχι λέοντα<br>Ὑψηὶς κατέπεφνε βοῶν σίνιν Εὐρυπύλοιο.", "st": "H2"}, {"sp": "N", "t": "οὐ κείνου χορὸν εἶδε θεώτερον ἄλλον Ἀπόλλων,<br>οὐδὲ πόλει τόσ’ ἔνειμεν ὀφέλσιμα, τόσσα Κυρήνηι,<br>μνωόμενος προτέρης ἁρπακτύος. οὐδὲ μὲν αὐτοί<br>Βαττιάδαι Φοίβοιο πλέον θεὸν ἄλλον ἔτεισαν.<br>ἱὴ ἱὴ παιῆον ἀκούομεν, οὕνεκα τοῦτο<br>Δελφός τοι πρώτιστον ἐφύμνιον εὕρετο λαός,<br>ἦμος ἑκηβολίην χρυσέων ἐπεδείκνυσο τόξων.<br>Πυθώ τοι κατιόντι συνήντετο δαιμόνιος θήρ,<br>αἰνὸς ὄφις. τὸν μὲν σὺ κατήναρες ἄλλον ἐπ’ ἄλλωι<br>βάλλων ὠκὺν ὀιστόν, ἐπηύτησε δὲ λαός,<br>‘ἱὴ ἱὴ παιῆον, ἵει βέλος, εὐθύ σε μήτηρ<br>γείνατ’ ἀοσσητῆρα’· τὸ δ’ ἐξέτι κεῖθεν ἀείδηι.<br>ὁ Φθόνος Ἀπόλλωνος ἐπ’ οὔατα λάθριος εἶπεν<br>‘οὐκ ἄγαμαι τὸν ἀοιδὸν ὃς οὐδ’ ὅσα πόντος ἀείδει’.<br>τὸν Φθόνον ὡπόλλων ποδί τ’ ἤλασεν ὧδέ τ’ ἔειπεν·<br>‘Ἀσσυρίου ποταμοῖο μέγας ῥόος, ἀλλὰ τὰ πολλά<br>λύματα γῆς καὶ πολλὸν ἐφ’ ὕδατι συρφετὸν ἕλκει.<br>Δηοῖ δ’ οὐκ ἀπὸ παντὸς ὕδωρ φορέουσι μέλισσαι,<br>ἀλλ’ ἥτις καθαρή τε καὶ ἀχράαντος ἀνέρπει<br>πίδακος ἐξ ἱερῆς ὀλίγη λιβὰς ἄκρον ἄωτον’.<br>χαῖρε ἄναξ· ὁ δὲ Μῶμος, ἵν’ ὁ Φθόνος, ἔνθα νέοιτο.", "st": "H2"}, {"sp": "SEC", "t": "Εἰς Ἄρτεμιν", "st": "H3"}, {"sp": "N", "t": "Ἄρτεμιν (οὐ γὰρ ἐλαφρὸν ἀειδόντεσσι λαθέσθαι)<br>ὑμνέομεν, τῆι τόξα λαγωβολίαι τε μέλονται<br>καὶ χορὸς ἀμφιλαφὴς καὶ ἐν οὔρεσιν ἑψιάασθαι,<br>ἄρχμενοι, ὡς ὅτε πατρὸς ἐφεζομένη γονάτεσσι<br>παῖς ἔτι κουρίζουσα τάδε προσέειπε γονῆα<br>‘δός μοι παρθενίην αἰώνιον ἄππα φυλάσσειν,<br>καὶ πολυωνυμίην, ἵνα μή μοι Φοῖβος ἐρίζηι.<br>δὸς δ’ ἰοὺς καὶ τόξα — ἔα πάτερ, οὔ σε φαρέτρην<br>οὐδ’ αἰτέω μέγα τόξον· ἐμοὶ Κύκλωπες ὀιστοὺς<br>αὐτίκα τεχνήσονται, ἐμοὶ δ’ εὐκαμπὲς ἄεμμα·<br>ἀλλὰ φαεσφορίην τε καὶ ἐς γόνυ μέχρι χιτῶνα<br>ζώννυσθαι λεγνωτόν, ἵν’ ἄγρια θηρία καίνω.<br>δὸς δέ μοι ἑξήκοντα χορίτιδας Ὠκεανίνας,<br>πάσας εἰνέτεας, πάσας ἔτι παῖδας ἀμίτρους.<br>δὸς δέ μοι ἀμφιπόλους Ἀμνισίδας εἴκοσι νύμφας,<br>αἵ τέ μοι ἐνδρομίδας τε καί, ὁππότε μηκέτι λύγκας<br>μήτ’ ἐλάφους βάλλοιμι, θοοὺς κύνας εὖ κομέοιεν,<br>δὸς δέ μοι οὔρεα πάντα· πόλιν δέ μοι ἥντινα νεῖμον<br>ἥντινα λῆις· σπαρνὸν γὰρ ὅτ’ Ἄρτεμις ἄστυ κάτεισιν·<br>οὔρεσιν οἰκήσω, πόλεσιν δ’ ἐπιμείξομαι ἀνδρῶν<br>μοῦνον ὅτ’ ὀξείηισιν ὑπ’ ὠδίνεσσι γυναῖκες<br>τειρόμεναι καλέουσι βοηθόον, ἧισί με Μοῖραι<br>γεινομένην τὸ πρῶτον ἐπεκλήρωσαν ἀρήγειν,<br>ὅττι με καὶ τίκτουσα καὶ οὐκ ἤλγησε φέρουσα<br>μήτηρ, ἀλλ’ ἀμογητὶ φίλων ἀπεθήκατο γυίων’.", "st": "H3"}, {"sp": "N", "t": "ὣς ἡ παῖς εἰποῦσα γενειάδος ἤθελε πατρὸς<br>ἅψασθαι, πολλὰς δὲ μάτην ἐτανύσσατο χεῖρας,<br>μέχρις ἵνα ψαύσειε. πατὴρ δ’ ἐπένευσε γελάσσας,<br>φῆ δὲ καταρρέζων ‘ὅτε μοι τοιαῦτα θέαιναι<br>τίκτοιεν, τυτθόν κεν ἐγὼ ζηλήμονος Ἥρης<br>χωομένης ἀλέγοιμι. φέρευ τέκος ὅσσ’ ἐθελημός<br>αἰτίζεις, καὶ δ’ ἄλλα πατὴρ ἔτι μείζονα δώσει.<br>τρὶς δέκα τοι πτολίεθρα καὶ οὐχ ἕνα πύργον ὀπάσσω,<br>τρὶς δέκα τοι πτολίεθρα, τὰ μὴ θεὸν ἄλλον ἀέξειν<br>εἴσεται ἀλλὰ μόνην σὲ καὶ Ἀρτέμιδος καλέεσθαι·<br>πολλὰς δὲ ξυνῆι πόλιας διαμετρήσασθαι<br>μεσσόγεως νήσους τε· καὶ ἐν πάσηισιν ἔσονται<br>Ἀρτέμιδος βωμοί τε καὶ ἄλσεα. καὶ μὲν ἀγυιαῖς<br>ἔσσηι καὶ λιμένεσσιν ἐπίσκοπος’. ὣς ὃ μὲν εἰπὼν<br>μῦθον ἐπεκρήηνε καρήατι. βαῖνε δὲ κούρη<br>λευκὸν ἐπὶ Κρηταῖον ὄρος κεκομημένον ὕληι·<br>ἔνθεν ἐπ’ Ὠκεανόν· πολέας δ’ ἐπελέξατο νύμφας,<br>[πάσας εἰνέτεας, πάσας ἔτι παῖδας ἀμίτρους.]<br>χαῖρε δὲ Καίρατος ποταμὸς μέγα, χαῖρε δὲ Τηθύς,<br>οὕνεκα θυγατέρας Λητωίδι πέμπον ἀμορβούς.", "st": "H3"}, {"sp": "N", "t": "αὖθι δὲ Κύκλωπας μετεκίαθε· τοὺς μὲν ἔτετμε<br>νήσωι ἐνὶ Λιπάρηι (Λιπάρη νέον, ἀλλὰ τότ’ ἔσκεν<br>οὔνομά οἱ Μελιγουνίς) ἐπ’ ἄκμοσιν Ἡφαίστοιο<br>ἑσταότας περὶ μύδρον· ἐπείγετο γὰρ μέγα ἔργον·<br>ἱππείην τετύκοντο Ποσειδάωνι ποτίστρην.<br>αἱ νύμφαι δ’ ἔδδεισαν, ὅπως ἴδον αἰνὰ πέλωρα<br>πρηόσιν †ὀσσείοισιν ἐοικότα, πᾶσι δ’ ὑπ’ ὀφρύν<br>φάεα μουνόγληνα σάκει ἴσα τετραβοείωι<br>δεινὸν ὑπογλαύσσοντα, καὶ ὁππότε δοῦπον ἄκουσαν<br>ἄκμονος ἠχήσαντος ἐπὶ μέγα πουλύ τ’ ἄημα<br>φυσάων αὐτῶν τε βαρὺν στόνον· αὖε γὰρ Αἴτνη,<br>αὖε δὲ Τρινακίη, Σικανῶν ἕδος, αὖε δὲ γείτων<br>Ἰταλίη, μεγάλην δὲ βοὴν ἐπὶ Κύρνος ἀύτει,<br>εὖθ’ οἵ γε ρῥαιστῆρας ἀειράμενοι ὑπὲρ ὤμων<br>ἢ χαλκὸν ζείοντα καμινόθεν ἠὲ σίδηρον<br>ἀμβολαδὶς τετυπόντες ἐπὶ μέγα μοχθήσειαν.<br>τῶι σφέας οὐκ ἐτάλασσαν ἀκηδέες Ὠκεανῖναι<br>οὔτ’ ἄντην ἰδέειν οὔτε κτύπον οὔασι δέχθαι.<br>οὐ νέμεσις· κείνους γε καὶ αἱ μάλα μηκέτι τυτθαί<br>οὐδέποτ’ ἀφρικτὶ μακάρων ὁρόωσι θύγατρες.", "st": "H3"}, {"sp": "N", "t": "ἀλλ’ ὅτε κουράων τις ἀπειθέα μητέρι τεύχοι,<br>μήτηρ μὲν Κύκλωπας ἑῆι ἐπὶ παιδὶ καλιστρεῖ,<br>Ἄργην ἢ Στερόπην· ὃ δὲ δώματος ἐκ μυχάτοιο<br>ἔρχεται Ἑρμείης σποδιῆι κεχριμένος αἰθῆι·<br>αὐτίκα τὴν κούρην μορμύσσεται, ἣ δὲ τεκούσης<br>δύνει ἔσω κόλπους θεμένη ἐπὶ φάεσι χεῖρας.<br>κοῦρα σὺ δὲ προτέρω περ, ἔτι τριέτηρος ἐοῦσα,<br>εὖτ’ ἔμολεν Λητώ σε μετ’ ἀγκαλίδεσσι φέρουσα,<br>Ἡφαίστου καλέοντος ὅπως ὀπτήρια δοίη,<br>Βρόντεώ σε στιβαροῖσιν ἐφεσσαμένου γονάτεσσι,<br>στήθεος ἐκ μεγάλου λασίης ἐδράξαο χαίτης,<br>ὤλοψας δὲ βίηιφι· τὸ δ’ ἄτριχον εἰσέτι καὶ νῦν<br>μεσσάτιον στέρνοιο μένει μέρος, ὡς ὅτε κόρσηι<br>φωτὸς ἐνιδρυθεῖσα κόμην ἐπενείματ’ ἀλώπηξ.<br>τῶι μάλα θαρσαλέη σφε τάδε προσελέξαο τῆμος<br>‘Κύκλωπες κἠμοί τι Κυδώνιον εἰ δ’ ἄγε τόξον<br>ἠδ’ ἰοὺς κοίλην τε κατακληῖδα βελέμνων<br>τεύξατε· καὶ γὰρ ἐγὼ Λητωιὰς ὥσπερ Ἀπόλλων.<br>αἰ δέ κ’ ἐγὼ τόξοις μονιὸν δάκος ἤ τι πέλωρον<br>θηρίον ἀγρεύσω, τὸ δέ κεν Κύκλωπες ἔδοιεν’.<br>ἔννεπες· οἳ δ’ ἐτέλεσσαν· ἄφαρ δ’ ὡπλίσσαο δαῖμον.", "st": "H3"}, {"sp": "N", "t": "αἶψα δ’ ἐπὶ σκύλακας πάλιν ἤιες· ἵκεο δ’ αὖλιν<br>Ἀρκαδικὴν ἔπι Πανός. ὃ δὲ κρέα λυγκὸς ἔταμνε<br>Μαιναλίης, ἵνα οἱ τοκάδες κύνες εἶδαρ ἔδοιεν.<br>τὶν δ’ ὁ γενειήτης δύο μὲν κύνας ἥμισυ πηγούς<br>τρεῖς δὲ παρουαίους ἕνα δ’ αἰόλον, οἵ ῥα λέοντας<br>αὐτοὺς αὖ ἐρύοντας, ὅτε δράξαιντο δεράων,<br>εἷλκον ἔτι ζώοντας ἐπ’ αὐλίον, ἑπτὰ δ’ ἔδωκε<br>θάσσονας αὐράων Κυνοσουρίδας, αἵ ῥα διῶξαι<br>ὤκισται νεβρούς τε καὶ οὐ μύοντα λαγωόν,<br>καὶ κοίτην ἐλάφοιο καὶ ὕστριχος ἔνθα καλιαί<br>σημῆναι, καὶ ζορκὸς ἐπ’ ἴχνιον ἡγήσασθαι.<br>ἔνθεν ἀπερχομένη (μετὰ καὶ κύνες ἐσσεύοντο)<br>εὗρες ἐπὶ προμολῆισ’ ὄρεος τοῦ Παρρασίοιο<br>σκαιρούσας ἐλάφους, μέγα τι χρέος· αἳ μὲν ἐπ’ ὄχθηις<br>αἰὲν ἐβουκολέοντο μελαμψήφιδος ἀναύρου,<br>μάσσονες ἢ ταῦροι, κεράων δ’ ἀπελάμπετο χρυσός·<br>ἐξαπίνης δ’ ἔταφές τε καὶ ὃν ποτὶ θυμὸν ἔειπες<br>‘τοῦτό κεν Ἀρτέμιδος πρωτάγριον ἄξιον εἴη’.<br>πέντ’ ἔσαν αἱ πᾶσαι· πίσυρας δ’ ἕλες ὦκα θέουσα<br>νόσφι κυνοδρομίης, ἵνα τοι θοὸν ἅρμα φέρωσι.<br>τὴν δὲ μίαν Κελάδοντος ὑπὲρ ποταμοῖο φυγοῦσαν<br>Ἥρης ἐννεσίηισιν, ἀέθλιον Ἡρακλῆι<br>ὕστερον ὄφρα γένοιτο, πάγος Κερύνειος ἔδεκτο.", "st": "H3"}, {"sp": "N", "t": "Ἄρτεμι Παρθενίη Τιτυοκτόνε, χρύσεα μέν τοι<br>ἔντεα καὶ ζώνη, χρύσεον δ’ ἐζεύξαο δίφρον,<br>ἐν δ’ ἐβάλευ χρύσεια θεὴ κεμάδεσσι χαλινά.<br>ποῦ δέ σε τὸ πρῶτον κερόεις ὄχος ἤρξατ’ ἀείρειν;<br>Αἵμωι ἐπὶ Θρήικι, τόθεν βορέαο κατᾶιξ<br>ἔρχεται ἀχλαίνοισι δυσαέα κρυμὸν ἄγουσα.<br>ποῦ δ’ ἔταμες πεύκην, ἀπὸ δὲ φλογὸς ἥψαο ποίης;<br>Μυσῶι ἐν Οὐλύμπωι, φάεος δ’ ἐνέηκας ἀυτμήν<br>ἀσβέστου, τό ῥα πατρὸς ἀποστάζουσι κεραυνοί.<br>ποσσάκι δ’ ἀργυρέοιο θεὴ πειρήσαο τόξου;<br>πρῶτον ἐπὶ πτελέην, τὸ δὲ δεύτερον ἧκας ἐπὶ δρῦν,<br>τὸ τρίτον αὖτ’ ἐπὶ θῆρα. τὸ τέτρατον οὐκέτ’ ἐπὶ δρῦν,<br>…", "st": "H3"}, {"sp": "N", "t": "ἀλλά μιν εἰς ἀδίκων ἔβαλες πόλιν, οἵ τε περὶ σφέας<br>οἵ τε περὶ ξείνους ἀλιτήμονα πολλὰ τέλεσκον,<br>σχέτλιοι· οἷς τύνη χαλεπὴν ἐμμάξεαι ὀργήν·<br>κτήνεά φιν λοιμὸς καταβόσκεται, ἔργα δὲ πάχνη,<br>κείρονται δὲ γέροντες ἐφ’ υἱάσιν, αἱ δὲ γυναῖκες<br>ἢ βληταὶ θνήισκουσι λεχωίδες ἠὲ φυγοῦσαι<br>τίκτουσιν τῶν οὐδὲν ἐπὶ σφυρὸν ὀρθὸν ἀνέστη.<br>οἷς δέ κεν εὐμειδής τε καὶ ἵλαος αὐγάσσηαι,<br>κείνοις εὖ μὲν ἄρουρα φέρει στάχυν, εὖ δὲ γενέθλη<br>τετραπόδων, εὖ δ’ ὄλβος ἀέξεται· οὐδ’ ἐπὶ σῆμα<br>ἔρχονται πλὴν εὖτε πολυχρόνιόν τι φέρωσιν·<br>οὐδὲ διχοστασίη τρώει γένος, ἥ τε καὶ εὖ περ<br>οἴκους ἑστηῶτας ἐσίνατο· ταὶ δὲ θυωρόν<br>εἰνάτερες γαλόωι τε μίαν πέρι δίφρα τίθενται.<br>πότνια, τῶν εἴη μὲν ἐμοὶ φίλος ὅστις ἀληθής,<br>εἴην δ’ αὐτός, ἄνασσα, μέλοι δέ μοι αἰὲν ἀοιδή·<br>τῆι ἔνι μὲν Λητοῦς γάμος ἔσσεται, ἐν δὲ σὺ πολλή,<br>ἐν δὲ καὶ Ἀπόλλων, ἐν δ’ οἵ σεο πάντες ἄεθλοι,<br>ἐν δὲ κύνες καὶ τόξα καὶ ἄντυγες, αἵ τέ σε ῥεῖα<br>θηητὴν φορέουσιν, ὅτ’ ἐς Διὸς οἶκον ἐλαύνεις.", "st": "H3"}, {"sp": "N", "t": "ἔνθα τοι ἀντιόωντες ἐνὶ προμολῆισι δέχονται<br>ὅπλα μὲν Ἑρμείης Ἀκακήσιος, αὐτὰρ Ἀπόλλων<br>θηρίον ὅττι φέρηισθα· πάροιθέ γέ, πρίν περ ἱκέσθαι<br>καρτερὸν Ἀλκεΐδην· νῦν δ’ οὐκέτι τοῦτον ἄεθλον<br>Φοῖβος ἔχει, τοῖος γὰρ ἀεὶ Τιρύνθιος ἄκμων<br>ἕστηκε πρὸ πυλέων ποτιδέγμενος, εἴ τι φέρουσα<br>νεῖαι πῖον ἔδεσμα· θεοὶ δ’ ἐπὶ πάντες ἐκείνωι<br>ἄλληκτον γελόωσι, μάλιστα δὲ πενθερὴ αὐτή,<br>ταῦρον ὅτ’ ἐκ δίφροιο μάλα μέγαν ἢ ὅ γε χλούνην<br>κάπρον ὀπισθιδίοιο φέροι ποδὸς ἀσπαίροντα·<br>κερδαλέωι μύθωι σε θεὴ μάλα τῶιδε πινύσκει<br>‘βάλλε κακοὺς ἐπὶ θῆρας, ἵνα θνητοί σε βοηθόν<br>ὡς ἐμὲ κικλήσκωσιν. ἔα πρόκας ἠδὲ λαγωούς<br>οὔρεα βόσκεσθαι· τί κέ μιν πρόκες ἠὲ λαγωοί<br>ῥέξειαν; σύες ἔργα, σύες φυτὰ λυμαίνονται.<br>καὶ βόες ἀνθρώποισι κακὸν μέγα· βάλλ’ ἐπὶ καὶ τούς.’<br>ὣς ἔνεπεν, ταχινὸς δὲ μέγαν περὶ θῆρα πονεῖτο.<br>οὐ γὰρ ὅ γε Φρυγίηι περ ὑπὸ δρυὶ γυῖα θεωθείς<br>παύσατ’ ἀδηφαγίης· ἔτι οἱ πάρα νηδὺς ἐκείνη,<br>τῆι ποτ’ ἀροτριόωντι συνήντετο Θειοδάμαντι.<br>σοὶ δ’ Ἀμνισιάδες μὲν ὑπὸ ζεύγληφι λυθείσας<br>ψήχουσιν κεμάδας, παρὰ δέ σφισι πουλὺ νέμεσθαι<br>Ἥρης ἐκ λειμῶνος ἀμησάμεναι φορέουσιν<br>ὠκύθοον τριπέτηλον, ὃ καὶ Διὸς ἵπποι ἔδουσιν·<br>ἐν καὶ χρυσείας ὑποληνίδας ἐπλήσαντο<br>ὕδατος, ὄφρ’ ἐλάφοισι ποτὸν θυμάρμενον εἴη.<br>αὐτὴ δ’ ἐς πατρὸς δόμον ἔρχεαι· οἳ δέ σ’ ἐφ’ ἕδρην<br>πάντες ὁμῶς καλέουσι· σὺ δ’ Ἀπόλλωνι παρίζεις.", "st": "H3"}, {"sp": "N", "t": "ἡνίκα δ’ αἱ νύμφαι σε χορῶι ἔνι κυκλώσονται<br>ἀγχόθι πηγάων Αἰγυπτίου Ἰνωποῖο<br>ἢ Πιτάνης (καὶ γὰρ Πιτάνη σέθεν) ἢ ἐνὶ Λίμναις,<br>ἢ ἵνα δαῖμον Ἀλὰς Ἀραφηνίδας οἰκήσουσα<br>ἦλθες ἀπὸ Σκυθίης, ἀπὸ δ’ εἴπαο τέθμια Ταύρων,<br>μὴ νειὸν τημοῦτος ἐμαὶ βόες εἵνεκα μισθοῦ<br>τετράγυον τέμνοιεν ὑπ’ ἀλλοτρίωι ἀροτῆρι·<br>ἦ γάρ κεν γυιαί τε καὶ αὐχένα κεκμηυῖαι<br>κόπρον ἔπι προγένοιντο, καὶ εἰ Στυμφαιίδες εἶεν<br>εἰναετιζόμεναι κεραελκέες, αἳ μέγ’ ἄρισται<br>τέμνειν ὦλκα βαθεῖαν· ἐπεὶ θεὸς οὔποτ’ ἐκεῖνον<br>ἦλθε παρ’ Ἠέλιος καλὸν χορόν, ἀλλὰ θεῆται<br>δίφρον ἐπιστήσας, τὰ δὲ φάεα μηκύνονται.<br>τίς δέ νύ τοι νήσων, ποῖον δ’ ὄρος εὔαδε πλεῖστον,<br>τίς δὲ λιμήν, ποίη δὲ πόλις; τίνα δ’ ἔξοχα νυμφέων<br>φίλαο, καὶ ποίας ἡρωίδας ἔσχες ἑταίρας;<br>εἰπὲ θεὴ σὺ μὲν ἄμμιν, ἐγὼ δ’ ἑτέροισιν ἀείσω.", "st": "H3"}, {"sp": "N", "t": "νήσων μὲν Δολίχη, πολίων δέ τοι εὔαδε Πέργη,<br>Τηύγετον δ’ ὀρέων, λιμένες γε μὲν Εὐρίποιο.<br>ἔξοχα δ’ ἀλλάων Γορτυνίδα φίλαο νύμφην,<br>ἐλλοφόνον Βριτόμαρτιν ἐύσκοπον· ἧς ποτε Μίνως<br>πτοιηθεὶς ὑπ’ ἔρωτι κατέδραμεν οὔρεα Κρήτης.<br>ἣ δ’ ὁτὲ μὲν λασίηισιν ὑπὸ δρυσὶ κρύπτετο νύμφη,<br>ἄλλοτε δ’ εἱαμενῆισιν· ὃ δ’ ἐννέα μῆνας ἐφοίτα<br>παίπαλά τε κρημνούς τε καὶ οὐκ ἀνέπαυσε διωκτύν,<br>μέσφ’ ὅτε μαρπτομένη καὶ δὴ σχεδὸν ἥλατο πόντον<br>πρηόνος ἐξ ὑπάτοιο καὶ ἔνθορεν εἰς ἁλιήων<br>δίκτυα, τά σφ’ ἐσάωσαν· ὅθεν μετέπειτα Κύδωνες<br>νύμφην μὲν Δίκτυναν, ὄρος δ’ ὅθεν ἥλατο νύμφη<br>Δικταῖον καλέουσιν, ἀνεστήσαντο δὲ βωμούς<br>ἱερά τε ῥέζουσι· τὸ δὲ στέφος ἤματι κείνωι<br>ἢ πίτυς ἢ σχῖνος, μύρτοιο δὲ χεῖρες ἄθικτοι·<br>δὴ τότε γὰρ πέπλοισιν ἐνέσχετο μύρσινος ὄζος<br>τῆς κούρης, ὅτ’ ἔφευγεν· ὅθεν μέγα χώσατο μύρτωι.<br>Οὖπι ἄνασσ’ εὐῶπι φαεσφόρε, καὶ δὲ σὲ κείνην<br>Κρηταέες καλέουσιν ἐπωνυμίην ἀπὸ νύμφης.", "st": "H3"}, {"sp": "N", "t": "καὶ μὴν Κυρήνην ἑταρίσσαο, τῆι ποτ’ ἔδωκας<br>αὐτὴ θηρητῆρε δύω κύνε, τοῖς ἔνι κούρη<br>Ὑψηὶς παρὰ τύμβον Ἰώλκιον ἔμμορ’ ἀέθλου.<br>καὶ Κεφάλου ξανθὴν ἄλοχον Δηιονίδαο<br>πότνια σὴν ὁμόθηρον ἐθήκαο· καὶ δὲ σὲ φασί<br>καλὴν Ἀντίκλειαν ἴσον φαέεσσι φιλῆσαι,<br>αἳ πρῶται θοὰ τόξα καὶ ἀμφ’ ὤμοισι φαρέτρας<br>ἰοδόκους ἐφόρησαν· ἀσύλλωτοι δέ φιν ὦμοι<br>δεξιτεροὶ καὶ γυμνὸς ἀεὶ παρεφαίνετο μαζός.<br>ἤινησας δ’ ἔτι πάγχυ ποδορρώρην Ἀταλάντην,<br>κούρην Ἰασίοιο συοκτόνον Ἀρκασίδαο,<br>καί ἑ κυνηλασίην τε καὶ εὐστοχίην ἐδίδαξας.<br>οὔ μιν ἐπίκλητοι Καλυδωνίου ἀγρευτῆρες<br>μέμφονται κάπροιο· τὰ γὰρ σημήια νίκης<br>Ἀρκαδίην εἰσῆλθεν, ἔχει δ’ ἔτι θηρὸς ὀδόντας·<br>οὐδὲ μὲν Ὑλαῖόν τε καὶ ἄφρονα Ῥοῖκον ἔολπα<br>οὐδέ περ ἐχθαίροντας ἐν Ἄιδι μωμήσασθαι<br>τοξότιν· οὐ γάρ σφιν λαγόνες συνεπιψεύσονται,<br>τάων Μαιναλίη νᾶεν φόνωι ἀκρώρεια.", "st": "H3"}, {"sp": "N", "t": "πότνια πουλυμέλαθρε πολύπτολι χαῖρε Χιτώνη<br>Μιλήτωι ἐπίδημε· σὲ γὰρ ποιήσατο Νηλεύς<br>ἡγεμόνην, ὅτε νηυσὶν ἀνήγετο Κεκροπίηθεν.<br>Χησιὰς Ἰμβρασίη πρωτόθρονε, σοὶ δ’ Ἀγαμέμνων<br>πηδάλιον νηὸς σφετέρης ἐγκάτθετο νηῶι<br>μείλιον ἀπλοΐης, ὅτε οἱ κατέδησας ἀήτας,<br>Τευκρῶν ἡνίκα νῆες Ἀχαιίδες ἄστεα κήδειν<br>ἔπλεον ἀμφ’ Ἑλένηι Ῥαμνουσίδι θυμωθεῖσαι.<br>ἦ μέν τοι Προῖτός γε δύω ἐκαθίσσατο νηούς,<br>ἄλλον μὲν Κορίης, ὅτι οἱ συνελέξαο κούρας<br>οὔρεα πλαζομένας Ἀζήνια, τὸν δ’ ἐνὶ Λούσοις<br>Ἡμέρηι, οὕνεκα θυμὸν ἀπ’ ἄγριον εἵλεο παίδων.<br>σοὶ καὶ Ἀμαζονίδες πολέμου ἐπιθυμήτειραι<br>ἔν ποτε παρραλίηι Ἐφέσωι βρέτας ἱδρύσαντο<br>φηγῶι ὑπὸ πρέμνωι, τέλεσεν δέ τοι ἱερὸν Ἱππώ·<br>αὐταὶ δ’, Οὖπι ἄνασσα, περὶ πρύλιν ὠρχήσαντο<br>πρῶτα μὲν ἐν σακέεσσιν ἐνόπλιον, αὖθι δὲ κύκλωι<br>στησάμεναι χορὸν εὐρύν· ὑπήεισαν δὲ λίγειαι<br>λεπταλέον σύριγγες, ἵνα ῥήσσωσιν ὁμαρτῆι<br>(οὐ γάρ πω νέβρεια δι’ ὀστέα τετρήναντο,<br>ἔργον Ἀθηναίης ἐλάφωι κακόν)· ἔδραμε δ’ ἠχώ<br>Σάρδιας ἔς τε νομὸν Βερεκύνθιον. αἳ δὲ πόδεσσιν<br>οὖλα κατεκροτάλιζον, ἐπεψόφεον δὲ φαρέτραι.", "st": "H3"}, {"sp": "N", "t": "κεῖνο δέ τοι μετέπειτα περὶ βρέτας εὐρὺ θέμειλον<br>δωμήθη, τοῦ δ’ οὔτι θεώτερον ὄψεται ἠώς<br>οὐδ’ ἀφνειότερον· ῥέα κεν Πυθῶνα παρέλθοι.<br>τῶι ῥα καὶ ἠλαίνων ἀλαπαξέμεν ἠπείλησε<br>Λύγδαμις ὑβριστής· ἐπὶ δὲ στρατὸν ἱππημολγῶν<br>ἤγαγε Κιμμερίων ψαμάθωι ἴσον, οἵ ῥα παρ’ αὐτόν<br>κεκλιμένοι ναίουσι βοὸς πόρον Ἰναχιώνης.<br>ἆ δειλὸς βασιλέων, ὅσον ἤλιτεν· οὐ γὰρ ἔμελλεν<br>οὔτ’ αὐτὸς Σκυθίηνδε παλιμπετὲς οὔτε τις ἄλλος<br>ὅσσων ἐν λειμῶνι Καϋστρίωι ἔσταν ἅμαζαι<br>νοστήσειν· Ἐφέσου γὰρ ἀεὶ τεὰ τόξα πρόκειται.<br>πότνια Μουνιχίη λιμενοσκόπε, χαῖρε Φεραίη.<br>μή τις ἀτιμήσηι τὴν Ἄρτεμιν (οὐδὲ γὰρ Οἰνεῖ<br>βωμὸν ἀτιμάσσαντι καλοὶ πόλιν ἦλθον ἀγῶνες),<br>μηδ’ ἐλαφηβολίην μηδ’ εὐστοχίην ἐριδαίνειν<br>(οὐδὲ γὰρ Ἀτρεΐδης ὀλίγωι ἔπι κόμπασε μισθῶι),<br>μηδέ τινα μνᾶσθαι τὴν παρθένον (οὐδὲ γὰρ Ὦτος,<br>οὐδὲ μὲν Ὠαρίων ἀγαθὸν γάμον ἐμνήστευσαν),<br>μηδὲ χορὸν φεύγειν ἐνιαύσιον (οὐδὲ γὰρ Ἱππώ<br>ἀκλαυτεὶ περὶ βωμὸν ἀπείπατο κυκλώσασθαι)·<br>χαῖρε μέγα κρείουσα καὶ εὐάντησον ἀοιδῆι.", "st": "H3"}, {"sp": "SEC", "t": "Εἰς Δῆλον", "st": "H4"}, {"sp": "N", "t": "τὴν ἱερήν, ὦ θυμέ, τίνα χρόνον ἢ πότ’ ἀείσεις<br>δῆλον, Ἀπόλλωνος κουροτρόφον; ἦ μὲν ἅπασαι<br>Κυκλάδες, αἳ νήσων ἱερώταται εἰν ἁλὶ κεῖνται,<br>εὔυμνοι· δῆλος δ’ ἐθέλει τὰ πρῶτα φέρεσθαι<br>ἐκ Μουσέων, ὅτι Φοῖβον ἀοιδάων μεδέοντα<br>λοῦσέ τε καὶ σπείρωσε καὶ ὡς θεὸν ἤινεσε πρώτη.<br>ὡς Μοῦσαι τὸν ἀοιδὸν ὃ μὴ Πίμπλειαν ἀείσηι<br>ἔχθουσιν, τὼς Φοῖβος ὅτις Δήλοιο λάθηται.<br>Δήλωι νῦν οἴμης ἀποδάσσομαι, ὡς ἂν Ἀπόλλων<br>Κύνθιος αἰνήσηι με φίλης ἀλέγοντα τιθήνης.<br>κείνη δ’ ἠνεμόεσσα καὶ ἄτροπος οἷά θ’ ἁλιπλήξ<br>αἰθυίηις καὶ μᾶλλον ἐπίδρομος ἠέπερ ἵπποις<br>πόντωι ἐνεστήρικται· ὃ δ’ ἀμφί ἑ πουλὺς ἑλίσσων<br>Ἰκαρίου πολλὴν ἀπομάσσεται ὕδατος ἄχνην·<br>τῶι σφε καὶ ἰχθυβολῆες ἁλίπλοοι ἐννάσσαντο.<br>ἀλλά οἱ οὐ νεμεσητὸν ἐνὶ πρώτηισι λέγεσθαι,<br>ὁππότ’ ἐς Ὠκεανόν τε καὶ ἐς Τιτηνίδα Τηθύν<br>νῆσοι ἀολλίζονται, ἀεὶ δ’ ἔξαρχος ὁδεύει.<br>ἣ δ’ ὄπιθεν Φοίνισσα μετ’ ἴχνια Κύρνος ὀπηδεῖ<br>οὐκ ὀνοτὴ καὶ Μάκρις Ἀβαντιὰς Ἐλλοπιήων<br>Σαρδώ θ’ ἱμερόεσσα καὶ ἣν ἐπενήξατο Κύπρις<br>ἐξ ὕδατος τὰ πρῶτα, σαοῖ δέ μιν ἀντ’ ἐπιβάθρων.", "st": "H4"}, {"sp": "N", "t": "κεῖναι μὲν πύργοισι περισκεπέεσσιν ἐρυμναί,<br>δῆλος δ’ Ἀπόλλωνι· τί δὲ στιβαρώτερον ἕρκος;<br>τείχεα μὲν καὶ λᾶες ὑπαὶ ῥιπῆς κε πέσοιεν<br>Στρυμονίου βορέαο· θεὸς δ’ ἀεὶ ἀστυφέλικτος·<br>Δῆλε φίλη, τοῖός σε βοηθόος ἀμφιβέβηκεν.<br>εἰ δὲ λίην πολέες σε περιτροχόωσιν ἀοιδαί,<br>ποίηι ἐνιπλέξω σε; τί τοι θυμῆρες ἀκοῦσαι;<br>ἢ ὡς τὰ πρώτιστα μέγας θεὸς οὔρεα θείνων<br>ἄορι τριγλώχινι, τό οἱ Τελχῖνες ἔτευξαν,<br>νήσους εἰναλίας εἰργάζετο, νέρθε δ’ ἐλάσσας<br>ἐκ νεάτων ὤχλισσε καὶ εἰσεκύλισε θαλάσσηι;<br>καὶ τὰς μὲν κατὰ βυσσόν, ἵν’ ἠπείροιο λάθωνται,<br>πρυμνόθεν ἐρρίζωσε· σὲ δ’ οὐκ ἔθλιψεν ἀνάγκη,<br>ἀλλ’ ἄφετος πελάγεσσιν ἐπέπλεες, οὔνομα δ’ ἦν τοι<br>Ἀστερίη τὸ παλαιόν, ἐπεὶ βαθὺν ἥλαο τάφρον<br>οὐρανόθεν φεύγουσα Διὸς γάμον ἀστέρι ἴση.<br>τόφρα μὲν οὔπω τοι χρυσέη ἐπεμίσγετο Λητώ,<br>τόφρα δ’ ἔτ’ Ἀστερίη σὺ καὶ οὐδέπω ἔκλεο Δῆλος.<br>πολλάκι σε Τροιζῆνος ἀπὸ ξάνθοιο πολίχνης<br>ἐρχόμενοι Ἐφύρηνδε Σαρωνικοῦ ἔνδοθι κόλπου<br>ναῦται ἐπεσκέψαντο, καὶ ἐξ Ἐφύρης ἀνιόντες<br>οἳ μὲν ἔτ’ οὐκ ἴδον αὖθι, σὺ δὲ στεινοῖο παρ’ ὀξύν<br>ἔδραμες Εὐρίποιο πόρον καναχηδὰ ῥέοντος,<br>Χαλκιδικῆς δ’ αὐτῆμαρ ἀνηναμένη ἁλὸς ὕδωρ<br>μέσφ’ ἐς Ἀθηναίων προσενήξαο Σούνιον ἄκρον<br>ἢ Χίον ἢ νήσοιο διάβροχον ὕδατι μαστόν<br>παρθενίης (οὔπω γὰρ ἔην Σάμος), ἧχί σε νύμφαι<br>γείτονες Ἀγκαίου Μυκαλησσίδες ἐξείνισσαν.", "st": "H4"}, {"sp": "N", "t": "ἡνίκα δ’ Ἀπόλλωνι γενέθλιον οὖδας ὑπέσχες,<br>τοῦτό τοι ἀντημοιβὸν ἁλίπλοοι οὔνομ’ ἔθεντο,<br>οὕνεκεν οὐκέτ’ ἄδηλος ἐπέπλεες, ἀλλ’ ἐνὶ πόντου<br>κύμασιν Αἰγαίοιο ποδῶν ἐνεθήκαο ῥίζας.<br>οὐδ’ Ἥρην κοτέουσαν ὑπέτρεσας· ἣ μὲν ἁπάσαις<br>δεινὸν ἐπεβρωμᾶτο λεχωίσιν αἳ Διὶ παῖδας<br>ἐξέφερον, Λητοῖ δὲ διακριδόν, οὕνεκα μούνη<br>Ζηνὶ τεκεῖν ἤμελλε φιλαίτερον Ἄρεος υἷα.<br>τῶι ῥα καὶ αὐτὴ μὲν σκοπιὴν ἔχεν αἰθέρος εἴσω<br>σπερχομένη μέγα δή τι καὶ οὐ φατόν, εἶργε δὲ Λητώ<br>τειρομένην ὠδῖσι· δύω δέ οἱ εἵατο φρουροί<br>γαῖαν ἐποπτεύοντες, ὃ μὲν πέδον ἠπείροιο<br>ἥμενος ὑψηλῆς κορυφῆς ἔπι Θρήικος Αἵμου<br>θοῦρος Ἄρης ἐφύλασσε σὺν ἔντεσι, τὼ δέ οἱ ἵππω<br>ἑπτάμυχον βορέαο παρὰ σπέος ηὐλίζοντο·<br>ἣ δ’ ἐπὶ νησάων ἑτέρη σκοπὸς εὐρειάων<br>ἧστο κόρη Θαύμαντος ἐπαΐξασα Μίμαντι.<br>ἔνθ’ οἳ μὲν πολίεσσιν ὅσαις ἐπεβάλλετο Λητώ<br>μίμνον ἀπειλητῆρες, ἀπετρώπων δὲ δέχεσθαι.", "st": "H4"}, {"sp": "N", "t": "φεῦγε μὲν Ἀρκαδίη, φεῦγεν δ’ ὄρος ἱερὸν Αὔγης<br>Παρθένιον, φεῦγεν δ’ ὁ γέρων μετόπισθε Φενειός.<br>φεῦγε δ’ ὅλη Πελοπηὶς ὅση παρακέκλιται Ἰσθμῶι,<br>ἔμπλην Αἰγιαλοῦ γε καὶ Ἄργεος· οὐ γὰρ ἐκείνας<br>ἀτραπιτοὺς ἐπάτησεν, ἐπεὶ λάχεν Ἴναχον Ἥρη.<br>φεῦγε καὶ Ἀονίη τὸν ἕνα δρόμον, αἳ δ’ ἐφέποντο<br>Δίρκη τε Στροφίη τε μελαμψήφιδος ἔχουσαι<br>Ἰσμηνοῦ χέρα πατρός, ὃ δ’ εἵπετο πολλὸν ὄπισθεν<br>Ἀσωπὸς βαρύγουνος, ἐπεὶ πεπάλακτο κεραυνῶι.<br>ἣ δ’ ὑποδινηθεῖσα χοροῦ ἀπεπαύσατο νύμφη<br>αὐτόχθων Μελίη καὶ ὑπόχλοον ἔσχε παρειήν<br>ἥλικος ἀσθμαίνουσα περὶ δρυός, ὡς ἴδε χαίτην<br>σειομένην Ἑλικῶνος. ἐμαὶ θεαί, εἴπατε Μοῦσαι,<br>ἦ ῥ’ ἐτεὸν ἐγένοντο τότε δρύες ἡνίκα Νύμφαι;<br>‘νύμφαι μὲν χαίρουσιν, ὅτε δρύας ὄμβρος ἀέξει,<br>νύμφαι δ’ αὖ κλαίουσιν, ὅτε δρυσὶν οὐκέτι φύλλα.’", "st": "H4"}, {"sp": "N", "t": "ταῖς μὲν ἔτ’ Ἀπόλλων ὑποκόλπιος αἰνὰ χολώθη,<br>φθέγξατο δ’ οὐκ ἀτέλεστον ἀπειλήσας ἐπὶ Θήβηι·<br>‘Θήβη τίπτε τάλαινα τὸν αὐτίκα πότμον ἐλέγχεις;<br>μήπω μή μ’ ἀέκοντα βιάζεο μαντεύεσθαι.<br>οὔπω μοι Πυθῶνι μέλει τριποδήιος ἕδρη,<br>οὐδέ τί πω τέθνηκεν ὄφις μέγας, ἀλλ’ ἔτι κεῖνο<br>θηρίον αἰνογένειον ἀπὸ Πλειστοῖο καθέρπον<br>Παρνησὸν νιφόεντα περιστέφει ἐννέα κύκλοις·<br>ἀλλ’ ἔμπης ἐρέω τι τορώτερον ἢ ἀπὸ δάφνης.<br>φεῦγε πρόσω· ταχινός σε κιχήσομαι αἵματι λούσων<br>τόξον ἐμόν· σὺ δὲ τέκνα κακογλώσσοιο γυναικός<br>ἔλλαχες. οὐ σύ γ’ ἐμεῖο φίλη τροφὸς οὐδὲ Κιθαιρών<br>ἔσσεται· εὐαγέων δὲ καὶ εὐαγέεσσι μελοίμην’.<br>ὣς ἄρ’ ἔφη. Λητὼ δὲ μετάτροπος αὖτις ἐχώρει.<br>ἀλλ’ ὅτ’ Ἀχαιιάδες μιν ἀπηρνήσαντο πόληες<br>ἐρχομένην, Ἑλίκη τε Ποσειδάωνος ἑταίρη<br>Βοῦρά τε Δεξαμενοῖο βοόστασις Οἰκιάδαο,<br>ἄψ δ’ ἐπὶ Θεσσαλίην πόδας ἔτρεπε, φεῦγε δ’ Ἄναυρος<br>καὶ μεγάλη Λάρισα καὶ αἱ Χειρωνίδες ἄκραι,<br>φεῦγε δὲ καὶ Πηνειὸς ἑλισσόμενος διὰ Τεμπέων·", "st": "H4"}, {"sp": "N", "t": "Ἥρη σοὶ δ’ ἔτι τῆμος ἀνηλεὲς ἦτορ ἔκειτο<br>οὐδὲ κατεκλάσθης τε καὶ ὤικτισας, ἡνίκα πήχεις<br>ἀμφοτέρους ὀρέγουσα μάτην ἐφθέγξατο τοῖα<br>‘Νύμφαι Θεσσαλίδες, ποταμοῦ γένος, εἴπατε πατρί<br>κοιμῆσαι μέγα χεῦμα· περιπλέξασθε γενείωι<br>λισσόμεναι τὰ Ζηνὸς ἐν ὕδατι τέκνα τεκέσθαι.<br>Πηνειὲ Φθιῶτα, τί νῦν ἀνέμοισιν ἐρίζεις;<br>ὦ πάτερ, οὐ μὴν ἵππον ἀέθλιον ἀμφιβέβηκας.<br>ἦ ῥά τοι ὧδ’ αἰεὶ ταχινοὶ πόδες, ἢ ἐπ’ ἐμεῖο<br>μοῦνοι ἐλαφρίζουσι, πεποίησαι δὲ πέτεσθαι<br>σήμερον ἐξαπίνης;’ ὃ δ’ ἀνήκοος. ‘ὦ ἐμὸν ἄχθος,<br>ποῖ σε φέρω; μέλεοι γὰρ ἀπειρήκασι τένοντες.<br>Πήλιον ὦ Φιλύρης νυμφήιον, ἀλλὰ σὺ μεῖνον,<br>μεῖνον, ἐπεὶ καὶ θῆρες ἐν οὔρεσι πολλάκι σεῖο<br>ὠμοτόκους ὠδῖνας ἀπηρείσαντο λέαιναι.’", "st": "H4"}, {"sp": "N", "t": "τὴν δ’ ἄρα καὶ Πηνειὸς ἀμείβετο δάκρυα λείβων<br>‘λητοῖ, Ἀναγκαίη μεγάλη θεός. οὐ γὰρ ἔγωγε<br>πότνια σὰς ὠδῖνας ἀναίνομαι (οἶδα καὶ ἄλλας<br>λουσαμένας ἀπ’ ἐμεῖο λεχωίδας)· ἀλλά μοι Ἥρη<br>δαψιλὲς ἠπείλησεν. ἀπαύγασαι, οἷος ἔφεδρος<br>οὔρεος ἐξ ὑπάτου σκοπιὴν ἔχει, ὅς κέ με ῥεῖα<br>βυσσόθεν ἐξερύσειε. τί μήσομαι; ἢ ἀπολέσθαι<br>ἡδύ τί τοι Πηνειόν; ἴτω πεπρωμένον ἦμαρ·<br>τλήσομαι εἵνεκα σεῖο καὶ εἰ μέλλοιμι ῥοάων<br>διψαλέην ἄμπωτιν ἔχων αἰώνιον ἔρρειν<br>καὶ μόνος ἐν ποταμοῖσιν ἀτιμότατος καλέεσθαι.<br>ἠνίδ’ ἐγώ· τί περισσά; κάλει μόνον Εἰλήθυιαν.’<br>εἶπε καὶ ἠρώησε μέγαν ῥόον. ἀλλά οἱ Ἄρης<br>Παγγαίου προθέλυμνα καρήατα μέλλεν ἀείρας<br>ἐμβαλέειν δίνηισιν, ἀποκρύψαι δὲ ῥέεθρα·<br>ὑψόθε δ’ ἐσμαράγησε καὶ ἀσπίδα τύψεν ἀκωκῆι<br>δούρατος· ἣ δ’ ἐλέλιξεν ἐνόπλιον· ἔτρεμε δ’ Ὄσσης<br>οὔρεα καὶ πεδίον Κραννώνιον αἵ τε δυσαεῖς<br>ἐσχατιαὶ Πίνδοιο, φόβωι δ’ ὠρχήσατο πᾶσα<br>Θεσσαλίη· τοῖος γὰρ ἀπ’ ἀσπίδος ἔβραμεν ἦχος.", "st": "H4"}, {"sp": "N", "t": "ὡς δ’ ὁπότ’ Αἰτναίου ὄρεος πυρὶ τυφομένοιο<br>σείονται μυχὰ πάντα κατουδαίοιο γίγαντος<br>εἰς ἑτέρην Βριαρῆος ἐπωμίδα κινυμένοιο,<br>θερμάστραι τε βρέμουσιν ὑφ’ Ἡφαίστοιο πυράγρης<br>ἔργα θ’ ὁμοῦ, δεινὸν δὲ πυρίκμητοί τε λέβητες<br>καὶ τρίποδες πίπτοντες ἐπ’ ἀλλήλοις ἰαχεῦσι·<br>τῆμος ἔγεντ’ ἄραβος σάκεος τόσος εὐκύκλοιο·<br>Πηνειὸς δ’ οὐκ αὖτις ἐχάζετο, μίμνε δ’ ὁμοίως<br>καρτερὸς ὡς τὰ πρῶτα, θοὰς δ’ ἐστήσατο δίνας,<br>εἰσόκε οἱ Κοιηὶς ἐκέκλετο ‘σώιζεο χαίρων,<br>σώιζεο· μὴ σύ γ’ ἐμεῖο πάθηις κακὸν εἵνεκα τῆσδε<br>ἀντ’ ἐλεημοσύνης, χάριτος δέ τοι ἔσσετ’ ἀμοιβή’.", "st": "H4"}, {"sp": "N", "t": "ἦ καὶ πολλὰ πάροιθεν ἐπεὶ κάμεν ἔστιχε νήσους<br>εἰναλίας· αἳ δ’ οὔ μιν ἐπερχομένην ἐδέχοντο,<br>οὐ λιπαρὸν νήεσσιν Ἐχινάδες ὅρμον ἔχουσαι,<br>οὐδ’ ἥτις Κέρκυρα φιλοξεινωτάτη ἄλλων,<br>Ἶρις ἐπεὶ πάσηισιν ἐφ’ ὑψηλοῖο Μίμαντος<br>σπερχομένη μάλα πολλὸν ἀπέτραπεν· αἳ δ’ ὑπ’ ὀμοκλῆς<br>πανσυδίηι φοβέοντο κατὰ ρῥόον ἥντινα τέτμοι.<br>ὠγυγίην δἤπειτα Κόων, Μεροπηίδα νῆσον,<br>ἵκετο, Χαλκιόπης ἱερὸν μυχὸν ἡρωίνης.<br>ἀλλά ἑ παιδὸς ἔρυκεν ἔπος τόδε ‘μὴ σύ γε μῆτερ<br>τῆι με τέκοις. οὔτ’ οὖν ἐπιμέμφομαι οὐδὲ μεγαίρω<br>νῆσον, ἐπεὶ λιπαρή τε καὶ εὔβοτος, εἴ νύ τις ἄλλη·<br>ἀλλά οἱ ἐκ Μοιρέων τις ὀφειλόμενος θεὸς ἄλλος<br>ἐστί, Σαωτήρων ὕπατον γένος· ὧι ὑπὸ μίτρην<br>ἵξεται οὐκ ἀέκουσα Μακηδόνι κοιρανέεσθαι<br>ἀμφοτέρη μεσόγεια καὶ αἳ πελάγεσσι κάθηνται,<br>μέχρις ὅπου περάτη τε καὶ ὁππόθεν ὠκέες ἵπποι<br>ἠέλιον φορέουσιν· ὃ δ’ εἴσεται ἤθεα πατρός.", "st": "H4"}, {"sp": "N", "t": "καί νύ ποτε ξυνός τις ἐλεύσεται ἄμμιν ἄεθλος<br>ὕστερον, ὁππότ’ ἂν οἳ μὲν ἐφ’ Ἑλλήνεσσι μάχαιραν<br>βαρβαρικὴν καὶ Κελτὸν ἀναστήσαντες Ἄρηα<br>ὀψίγονοι Τιτῆνες ἀφ’ ἑσπέρου ἐσχατόωντος<br>ῥώσωνται νιφάδεσσιν ἐοικότες ἢ ἰσάριθμοι<br>τείρεσιν, ἡνίκα πλεῖστα κατ’ ἠέρα βουκολέονται,<br>φρούρια καὶ …<br>καὶ πεδία Κρισσαῖα καὶ ἤπειροι …<br>ἀμφιπεριστείνωνται, ἴδωσι δὲ πίονα καπνὸν<br>γείτονος αἰθομένοιο, καὶ οὐκέτι μοῦνον ἀκουῆι,<br>ἀλλ’ ἤδη παρὰ νηὸν ἀπαυγάζωνται † φάλαγγες<br>δυσμενέων, ἤδη δὲ παρὰ τριπόδεσσιν ἐμεῖο<br>φάσγανα καὶ ζωστῆρας ἀναιδέας ἐχθομένας τε<br>ἀσπίδας, αἳ Γαλάτηισι κακὴν ὁδὸν ἄφρονι φύλωι<br>στήσονται· τέων αἳ μὲν ἐμοὶ γέρας, αἳ δ’ ἐπὶ Νείλωι<br>ἐν πυρὶ τοὺς φορέοντας ἀποπνεύσαντας ἰδοῦσαι<br>κείσονται βασιλῆος ἀέθλια πολλὰ καμόντος.", "st": "H4"}, {"sp": "N", "t": "ἐσσόμενε Πτολεμαῖε, τά τοι μαντήια φαίνω.<br>αἰνήσεις μέγα δή τι τὸν εἰσέτι γαστέρι μάντιν<br>ὕστερον ἤματα πάντα· σὺ δὲ ξυμβάλλεο μῆτερ·<br>ἔστι διειδομένη τις ἐν ὕδατι νήσος ἀραιή,<br>πλαζομένη πελάγεσσι· πόδες δέ οἱ οὐχ ἑνὶ χώρωι,<br>ἀλλὰ παλιρροίηι ἐπινήχεται ἀνθέρικος ὥς,<br>ἔνθα νότος, ἔνθ’ εὖρος, ὅπη φορέηισι θάλασσα.<br>τῆι με φέροις· κείνην γὰρ ἐλεύσεαι εἰς ἐθέλουσαν.’<br>αἳ μὲν τόσσα λέγοντος ἀπέτρεχον εἰν ἁλὶ νῆσοι·<br>Ἀστερίη φιλόμολπε, σὺ δ’ Εὐβοίηθε κατήιεις,<br>Κυκλάδας ὀψομένη περιηγέας, οὔ τι παλαιόν,<br>ἀλλ’ ἔτι τοι μετόπισθε Γεραίστιον εἵπετο φῦκος·<br>…<br>… φλεξας ἐπεὶ περικαίεο πυρί,<br>τλήμον’ ὑπ’ ὠδίνεσσι βαρυνομένην ὁρόωσα·<br>‘Ἥρη τοῦτό με ῥέξον ὅ τοι φίλον· οὐ γάρ ἀπειλὰς<br>ὑμετέρας ἐφύλαξα· πέρα, πέρα εἰς ἐμὲ Λητοῖ’.", "st": "H4"}, {"sp": "N", "t": "ἔννεπες· ἣ δ’ ἀρητὸν ἄλης ἀπεπαύσατο λυγρῆς,<br>ἕζετο δ’ Ἰνωποῖο παρὰ ρῥόον, ὅντε βάθιστον<br>γαῖα τότ’ ἐξανίησιν, ὅτε πλήθοντι ῥεέθρωι<br>Νεῖλος ἀπὸ κρημνοῖο κατέρχεται Αἰθιοπῆος·<br>λύσατο δὲ ζώνην, ἀπὸ δ’ ἐκλίθη ἔμπαλιν ὤμοις<br>φοίνικος ποτὶ πρέμνον ἀμηχανίης ὑπὸ λυγρῆς<br>τειρομένη· νότιος δὲ διὰ χροὸς ἔρρεεν ἱδρώς.<br>εἶπε δ’ ἀλυσθμαίνουσα ‘τί μητέρα κοῦρε βαρύνεις;<br>αὕτη τοι φίλε νῆσος ἐπιπλώουσα θαλάσσηι.<br>γείνεο, γείνεο κοῦρε καὶ ἤπιος ἔξιθι κόλπου’.<br>νύμφα Διὸς βαρύθυμε, σὺ δ’ οὐκ ἄρ’ ἔμελλες ἄπυστος<br>δὴν ἔμεναι· τοίη σε προσέδραμεν ἀγγελιῶτις,<br>εἶπε δ’ ἔτ’ ἀσθμαίνουσα, φόβωι δ’ ἀνεμίσγετο μῦθος,<br>‘Ἥρη τιμηέσσα, πολὺ προὔχουσα θεάων<br>σὴ μὲν ἐγώ, σὰ δὲ πάντα, σὺ δὲ κρείουσα κάθησαι<br>γνησίη Οὐλύμποιο, καὶ οὐ χέρα δείδιμεν ἄλλην<br>θηλυτέρην, σὺ δ’ ἄνασσα τὸν αἴτιον εἴσεαι ὀργῆς.<br>Λητώ τοι μίτρην ἀναλύεται ἔνδοθι νήσου.", "st": "H4"}, {"sp": "N", "t": "ἄλλαι μὲν πᾶσαί μιν ἀπέστυγον οὐδ’ ἐδέχοντο·<br>Ἀστερίη δ’ ὀνομαστὶ παρερχομένην ἐκάλεσσεν,<br>Ἀστερίη, πόντοιο κακὸν σάρον· οἶσθα καὶ αὐτή.<br>ἀλλὰ φίλη, δύνασαι γάρ, ἀμύνειν πότνια δούλοις<br>ὑμετέροις, οἳ σεῖο πέδον πατέουσιν ἐφετμῆι’.<br>ἦ καὶ ὑπὸ χρύσειον ἐδέθλιον ἷζε κύων ὥς,<br>Ἀρτέμιδος ἥτις τε, θοῆς ὅτε παύσεται ἄγρης,<br>ἵζει θηρήτειρα παρ’ ἴχνεσιν, οὔατα δ’ αὐτῆς<br>ὀρθὰ μάλ’, αἰὲν ἑτοῖμα θεῆς ὑποδέχθαι ὀμοκλήν·<br>τῆι ἰκέλη Θαύμαντος ὑπὸ θρόνον ἵζετο κούρη.<br>κείνη δ’ οὐδέποτε σφετέρης ἐπιλήθεται ἕδρης,<br>οὐδ’ ὅτε οἱ ληθαῖον ἐπὶ πτερὸν ὕπνος ἐρείσει,<br>ἀλλ’ αὐτοῦ μεγάλοιο ποτὶ γλωχῖνα θρόνοιο<br>τυτθὸν ἀποκλίνασα καρήατα λέχριος εὕδει.", "st": "H4"}, {"sp": "N", "t": "οὐδέ ποτε ζώνην ἀναλύεται οὐδὲ ταχείας<br>ἐνδρομίδας, μή οἵ τι καὶ αἰφνίδιον ἔπος εἴπηι<br>δεσπότις. ἣ δ’ ἀλεγεινὸν ἀλαστήσασα προσηύδα<br>‘οὕτω νῦν, ὦ Ζηνὸς ὀνείδεα, καὶ γαμέοισθε<br>λάθρια καὶ τίκτοιτε κεκρυμμένα, μηδ’ ὅθι δειλαί<br>δυστοκέες μογέουσιν ἀλετρίδες, ἀλλ’ ὅθι φῶκαι<br>εἰνάλιαι τίκτουσιν, ἐνὶ σπιλάδεσσιν ἐρήμοις.<br>Ἀστερίηι δ’ οὐδέν τι βαρύνομαι εἵνεκα τῆσδε<br>ἀμπλακίης, οὐδ’ ἔστιν ὅπως ἀποθύμια ῥέξω·<br>τόσσα δέω· μάλα γάρ τε κακῶς ἐχαρίσσατο Λητοῖ·<br>ἀλλά μιν ἔκπαγλόν τι σεβίζομαι, οὕνεκ’ ἐμεῖο<br>δέμνιον οὐκ ἐπάτησε, Διὸς δ’ ἀνθείλετο πόντον’.<br>ἣ μὲν ἔφη· κύκνοι δὲ θεοῦ μέλποντες ἄοζοι<br>Μηιόνιον Πακτωλὸν ἐκυκλώσαντο λιπόντες<br>ἑβδομάκις περὶ Δῆλον, ἐπήεισαν δὲ λοχείηι<br>Μουσάων ὄρνιθες, ἀοιδότατοι πετεηνῶν·<br>ἔνθεν ὁ παῖς τοσσάσδε λύρηι ἐνεδήσατο χορδάς<br>ὕστερον, ὁσσάκι κύκνοι ἐπ’ ὠδίνεσσιν ἄεισαν.<br>ὄγδοον οὐκέτ’ ἄεισαν, ὃ δ’ ἔκθορεν, αἳ δ’ ἐπὶ μακρὸν<br>νύμφαι Δηλιάδες, ποταμοῦ γένος ἀρχαίοιο,<br>εἶπαν Ἐλειθυίης ἱερὸν μέλος, αὐτίκα δ’ αἰθήρ<br>χάλκεος ἀντήχησε διαπρυσίην ὀλολυγήν,<br>οὐδ’ Ἥρη νεμέσησεν, ἐπεὶ χόλον ἐξέλετο Ζεύς.", "st": "H4"}, {"sp": "N", "t": "χρύσεά τοι τότε πάντα θεμείλια γείνετο Δῆλε,<br>χρυσῶι δὲ τροχόεσσα πανήμερος ἔρρεε λίμνη,<br>χρύσειον δ’ ἐκόμησε γενέθλιον ἔρνος ἐλαίης,<br>χρυσῶι δὲ πλήμυρε βαθὺς Ἰνωπὸς ἑλιχθείς.<br>αὐτὴ δὲ χρυσέοιο ἀπ’ οὔδεος εἵλεο παῖδα,<br>ἐν δ’ ἐβάλευ κόλποισιν, ἔπος δ’ ἐφθέγξαο τοῖον<br>‘ὦ μεγάλη πολύβωμε πολύπτολι πολλὰ φέρουσα,<br>πίονες ἤπειροί τε καὶ αἳ περιναίετε νῆσοι·<br>αὕτη ἐγὼ τοιήδε· δυσήροτος, ἀλλ’ ἀπ’ ἐμεῖο<br>Δήλιος Ἀπόλλων κεκλήσεται, οὐδέ τις ἄλλη<br>γαιάων τοσσόνδε θεῶι πεφιλήσεται ἄλλωι,<br>οὐ Κερχνὶς κρείοντι Ποσειδάωνι Λεχαίου,<br>οὐ πάγος Ἑρμείηι Κυλλήνιος, οὐ Διὶ Κρήτη,<br>ὡς ἐγὼ Ἀπόλλωνι· καὶ ἔσσομαι οὐκέτι πλαγκτή.’<br>ὧδε σὺ μὲν κατέλεξας· ὃ δὲ γλυκὺν ἔσπασε μαζόν.", "st": "H4"}, {"sp": "N", "t": "τῶι καὶ νησάων ἁγιωτάτη ἐξέτι κείνου<br>κλήζηι, Ἀπόλλωνος κουροτρόφος· οὐδέ σ’ Ἐνυώ<br>οὐδ’ Ἀίδης οὐδ’ ἵπποι ἐπιστείβουσιν Ἄρηος·<br>ἀλλά τοι ἀμφιετεῖς δεκατηφόροι αἰὲν ἀπαρχαί<br>πέμπονται, πᾶσαι δὲ χοροὺς ἀνάγουσι πόληες,<br>αἵ τε πρὸς ἠοίην αἵ θ’ ἕσπερον αἵ τ’ ἀνὰ μέσσην<br>κλήρους ἐστήσαντο, καὶ οἳ καθύπερθε βορείης<br>οἰκία θινὸς ἔχουσι, πολυχρονιώτατον αἷμα.<br>οἳ μέν τοι καλάμην τε καὶ ἱερὰ δράγματα πρῶτοι<br>ἀσταχύων φορέουσιν· ἃ Δωδώνηθι Πελασγοί<br>τηλόθεν ἐκβαίνοντα πολὺ πρώτιστα δέχονται,<br>γηλεχέες θεράποντες ἀσιγήτοιο λέβητος·<br>δεύτερον Ἱερὸν ἄστυ καὶ οὔρεα Μηλίδος αἴης<br>ἔρχονται· κεῖθεν δὲ διαπλώουσιν Ἀβάντων<br>εἰς ἀγαθὸν πεδίον Ληλάντιον· οὐδ’ ἔτι μακρός<br>ὁ πλόος Εὐβοίηθεν, ἐπεὶ σέο γείτονες ὅρμοι.<br>πρῶταί τοι τάδ’ ἔνεικαν ἀπὸ ξανθῶν Ἀριμασπῶν<br>Οὖπίς τε Λοξώ τε καὶ εὐαίων Ἑκαέργη,<br>θυγατέρες Βορέαο, καὶ ἄρσενες οἳ τότ’ ἄριστοι<br>ἠιθέων· οὐδ’ οἵ γε παλιμπετὲς οἴκαδ’ ἵκοντο,<br>εὔμοιροι δ’ ἐγένοντο, καὶ ἀκλέες οὔποτ’ ἐκεῖνοι.<br>ἦ τοι Δηλιάδες μέν, ὅτ’ εὐήχης ὑμέναιος<br>ἤθεα κουράων μορμύσσεται, ἥλικα χαίτην<br>παρθενικαῖς, παῖδες δὲ θέρος τὸ πρῶτον ἰούλων<br>ἄρσενες ἠιθέοισιν ἀπαρχόμενοι φορέουσιν.", "st": "H4"}, {"sp": "N", "t": "Ἀστερίη θυόεσσα, σὲ μὲν περί τ’ ἀμφί τε νῆσοι<br>κύκλον ἐποιήσαντο καὶ ὡς χορὸν ἀμφεβάλοντο·<br>οὔτε σιωπηλὴν οὔτ’ ἄψοφον οὖλος ἐθείραις<br>ἕσπερος, ἀλλ’ αἰεί σε καταβλέπει ἀμφιβόητον.<br>οἳ μὲν ὑπαείδουσι νόμον Λυκίοιο γέροντος,<br>ὅν τοι ἀπὸ Ξάνθοιο θεοπρόπος ἤγαγεν Ὠλήν·<br>αἳ δὲ ποδὶ πλήσσουσι χορίτιδες ἀσφαλὲς οὖδας.<br>δὴ τότε καὶ στεφάνοισι βαρύνεται ἱρὸν ἄγαλμα<br>Κύπριδος ἀρχαίης ἀριήκοον, ἥν ποτε Θησεύς<br>εἵσατο σὺν παίδεσσιν, ὅτε Κρήτηθεν ἀνέπλει.<br>οἳ χαλεπὸν μύκημα καὶ ἄγριον υἷα φυγόντες<br>Πασιφάης καὶ γναμπτὸν ἕδος σκολιοῦ λαβυρίνθου<br>πότνια σὸν περὶ βωμὸν ἐγειρομένου κιθαρισμοῦ<br>κύκλιον ὠρχήσαντο, χοροῦ δ’ ἡγήσατο Θησεύς.<br>ἔνθεν ἀειζώοντα θεωρίδος ἱερὰ Φοίβωι<br>Κεκροπίδαι πέμπουσι, τοπήια νηὸς ἐκείνης.<br>Ἀστερίη πολύβωμε πολύλλιτε, τίς δέ σε ναύτης<br>ἔμπορος Αἰγαίοιο παρήλυθε νηὶ θεούσηι;<br>οὐχ οὕτω μεγάλοι μιν ἐπιπνείουσιν ἀῆται,<br>χρειὼ δ’ ὅττι τάχιστον ἄγει πλόον, ἀλλὰ τὰ λαίφη<br>ὠκέες ἐστείλαντο καὶ οὐ πάλιν αὖτις ἔβησαν,<br>πρὶν μεγάλη σέο βωμὸν ὑπὸ πληγῆισιν ἑλίξαι<br>ῥησσόμενον καὶ πρέμνον ὀδακτάσαι ἁγνὸν ἐλαίης<br>χεῖρας ἀποστρέψαντας· ἃ Δηλιὰς εὕρετο νύμφη<br>παίγνια κουρίζοντι καὶ Ἀπόλλωνι γελαστύν.", "st": "H4"}, {"sp": "N", "t": "ἱστίη ὦ νήσων εὐέστιε χαῖρε μὲν αὐτή,<br>χαίροι δ’ Ἀπόλλων τε καὶ ἣν ἐλοχεύσαο Λητώ.", "st": "H4"}, {"sp": "SEC", "t": "Εἰς λουτρὰ τῆς Παλλάδος", "st": "H5"}, {"sp": "N", "t": "Ὅσσαι λωτροχόοι τᾶς Παλλάδος ἔξιτε πᾶσαι,<br>ἔξιτε· τᾶν ἵππων ἄρτι φρυασσομενᾶν<br>τᾶν ἱερᾶν ἐσάκουσα, καὶ ἁ θεὸς εὔτυκος ἕρπειν·<br>σοῦσθέ νυν, ὦ ξανθαί σοῦσθε Πελασγιάδες.<br>οὔποκ’ Ἀθαναία μεγάλως ἀπενίψατο πάχεις<br>πρὶν κόνιν ἱππειᾶν ἐξελάσαι λαγόνων,<br>οὐδ’ ὅκα δὴ λύθρωι πεπαλαγμένα πάντα φέροισα<br>τεύχεα τῶν ἀδίκων ἦνθ’ ἀπὸ γηγενέων,<br>ἀλλὰ πολὺ πράτιστον ὑφ’ ἅρματος αὐχένας ἵππων<br>λυσαμένα παγαῖς ἔκλυσεν Ὠκεανῶ<br>ἱδρῶ καὶ ῥαθάμιγγας, ἐφοίβασεν δὲ παγέντα<br>πάντα χαλινοφάγων ἀφρὸν ἀπὸ στομάτων.<br>ὦ ἴτ’ Ἀχαιιάδες, καὶ μὴ μύρα μηδ’ ἀλαβάστρως<br>(συρίγγων ἀίω φθόγγον ὑπαξονίων),<br>μὴ μύρα λωτροχόοι τᾶι Παλλάδι μηδ’ ἀλαβάστρως<br>(οὐ γὰρ Ἀθαναία χρίματα μεικτὰ φιλεῖ)<br>οἴσετε μηδὲ κάτοπτρον· ἀεὶ καλὸν ὄμμα τὸ τήνας<br>οὐδ’ ὅκα τὰν Ἴδαι Φρὺξ ἐδίκαζεν ἔριν,<br>οὔτ’ ἐς ὀρείχαλκον μεγάλα θεὸς οὔτε Σιμοῦντος<br>ἔβλεψεν δίναν ἐς διαφαινομέναν·", "st": "H5"}, {"sp": "N", "t": "οὐδ’ Ἥρα· Κύπρις δὲ διαυγέα χαλκὸν ἑλοῖσα<br>πολλάκι τὰν αὐτὰν δὶς μετέθηκε κόμαν·<br>ἃ δέ, δὶς ἑξήκοντα διαθρέξασα διαύλως,<br>οἷα παρ’ Εὐρώται τοὶ Λακεδαιμόνιοι<br>ἀστέρες, ἐμπεράμως ἐνετρίψατο λιτὰ βαλοῖσα<br>χρίματα, τᾶς ἰδίας ἔκγονα φυταλιᾶς·<br>ὦ κῶραι, τὸ δ’ ἔρευθος ἀνέδραμε, πρώιον οἵαν<br>ἢ ῥόδον ἢ σίβδας κόκκος ἔχει χροΐαν.<br>τῶι καὶ νῦν ἄρσεν τι κομίξατε μῶνον ἔλαιον,<br>ὧι Κάστωρ, ὧι καὶ χρίεται Ἡρακλέης·<br>οἴσετε καὶ κτένα οἱ παγχρύσεον, ὡς ἀπὸ χαίταν<br>πέξηται, λιπαρὸν σμασαμένα πλόκαμον.", "st": "H5"}, {"sp": "N", "t": "ἔξιθ’ Ἀθαναία· πάρα τοι καταθύμιος ἴλα,<br>παρθενικαὶ μεγάλων παῖδες Ἀρεστοριδᾶν·<br>ὠθάνα, φέρεται δὲ καὶ ἁ Διομήδεος ἀσπίς,<br>ὡς ἔθος Ἀργείων τοῦτο παλαιότερον·<br>…<br>…<br>Εὐμήδης ἐδίδαξε, τεὶν κεχαρισμένος ἱρεύς·<br>ὅς ποκα βωλευτὸν γνοὺς ἐπί οἱ θάνατον<br>δᾶμον ἑτοιμάζοντα φυγᾶι τεὸν ἱρὸν ἄγαλμα<br>ὤιχετ’ ἔχων, Κρεῖον δ’ εἰς ὄρος ὠικίσατο·<br>κρεῖον ὄρος· σὲ δὲ δαῖμον ἀπορρώγεσσιν ἔθηκεν<br>ἐν πέτραις, αἷς νῦν οὔνομα Παλλατίδες.<br>ἔξιθ’ Ἀθαναία περσέπτολι χρυσεοπήληξ,<br>ἵππων καὶ σακέων ἁδομένα πατάγωι.<br>σάμερον ὑδροφόροι μὴ βάπτετε — σάμερον Ἄργος<br>πίνετ’ ἀπὸ κρανᾶν μηδ’ ἀπὸ τῶ ποταμῶ,<br>σάμερον αἱ δῶλαι τὰς κάλπιδας ἢ ’ς Φυσάδειαν<br>ἢ ἐς Ἀμυμώναν οἴσετε τὰν Δαναῶ.<br>καὶ γὰρ δὴ χρυσῶι τε καὶ ἄνθεσιν ὕδατα μείξας<br>ἡξεῖ φορβαίων Ἴναχος ἐξ ὀρέων<br>τἀθάναι τὸ λοετρὸν ἄγων καλόν. ἀλλὰ Πελασγέ<br>φράζεο μὴ οὐκ ἐθέλων τὰν βασίλειαν ἴδηις.<br>ὅς κεν ἴδηι γυμνὰν τὰν Παλλάδα τὰν πολιοῦχον,<br>τὦργος ἐσοψεῖται τοῦτο πανυστάτιον.", "st": "H5"}, {"sp": "N", "t": "πότνι’ Ἀθαναία τὺ μὲν ἔξιθι· μέσφα δ’ ἐγώ τι<br>ταῖσδ’ ἐρέω. μῦθος δ’ οὐκ ἐμός, ἀλλ’ ἑτέρων.<br>παῖδες, Ἀθαναία νύμφαν μίαν ἔν ποκα Θήβαις<br>πουλύ τι καὶ πέρι δὴ φίλατο τᾶν ἑταρᾶν,<br>ματέρα Τειρεσίαο, καὶ οὔποκα χωρὶς ἔγεντο·<br>ἀλλὰ καὶ ἀρχαίων εὖτ’ ἐπὶ Θεσπιέων<br>…; ἢ εἰς Ἁλίαρτον ἐλαύνοι<br>ἵππως, Βοιωτῶν ἔργα διερχομένα,<br>ἢ ’πὶ Κορωνείας, ἵνα οἱ τεθυωμένον ἄλσος<br>καὶ βωμοὶ ποταμῶι κεῖντ’ ἐπὶ Κουραλίωι·<br>πολλάκις ἁ δαίμων νιν ἑῶ ἐπεβάσατο δίφρω,<br>οὐδ’ ὄαροι νυμφᾶν οὐδὲ χοροστασίαι<br>ἁδεῖαι τελέθεσκον, ὅκ’ οὐχ ἁγεῖτο Χαρικλώ·<br>ἀλλ’ ἔτι καὶ τήναν δάκρυα πόλλ’ ἔμενεν,<br>καίπερ Ἀθαναίαι καταθύμιον ἔσσαν ἑταίραν.<br>δή ποκα γὰρ πέπλων λυσομένα περόνας<br>ἵππω ἐπὶ κράναι Ἑλικωνίδι καλὰ ῥεοίσαι<br>λῶντο· μεσαμβρινὰ δ’ εἶχ’ ὄρος ἁσυχία.<br>ἀμφότεραι λώοντο, μεσαμβριναὶ δ’ ἔσαν ὧραι,<br>πολλὰ δ’ ἁσυχία τῆνο κατεῖχεν ὄρος.", "st": "H5"}, {"sp": "N", "t": "Τειρεσίας δ’ ἔτι μῶνος ἁμᾶ κυσὶν ἄρτι γένεια<br>περκάζων ἱερὸν χῶρον ἀνεστρέφετο·<br>διψάσας δ’ ἄφατόν τι ποτὶ ρῥόον ἤλυθε κράνας,<br>σχέτλιος· οὐκ ἐθέλων δ’ εἶδε τὰ μὴ θεμιτά·<br>τὸν δὲ χολωσαμένα περ ὅμως προσέφασεν Ἀθάνα<br>‘τίς σε, τὸν ὀφθαλμὼς οὐκέτ’ ἀποισόμενον,<br>ὦ Εὐηρείδα, χαλεπὰν ὁδὸν ἄγαγε δαίμων;’<br>ἃ μὲν ἔφα, παιδὸς δ’ ὄμματα νὺξ ἔλαβεν.<br>ἑστάκη δ’ ἄφθογγος, ἐκόλλασαν γὰρ ἀνῖαι<br>γώνατα καὶ φωνὰν ἔσχεν ἀμηχανία.<br>ἁ νύμφα δ’ ἐβόασε ‘τί μοι τὸν κῶρον ἔρεξας<br>πότνια; τοιαῦται δαίμονες ἐστὲ φίλαι;<br>ὄμματά μοι τῶ παιδὸς ἀφείλεο. τέκνον ἄλαστε<br>εἶδες Ἀθαναίας στήθεα καὶ λαγόνας,<br>ἀλλ’ οὐκ ἀέλιον πάλιν ὄψεαι. ὦ ἐμὲ δειλάν,<br>ὦ ὄρος, ὦ Ἑλικὼν οὐκέτι μοι παριτέ,<br>ἦ μεγάλ’ ἀντ’ ὀλίγων ἐπράξαο· δόρκας ὀλέσσας<br>καὶ πρόκας οὐ πολλὰς φάεα παιδὸς ἔχεις.’", "st": "H5"}, {"sp": "N", "t": "† ἁ μὲν ἀμφοτέραισι φίλον περὶ παῖδα λαβοῖσα<br>† μάτηρ μὲν γοερᾶν οἶτον ἀηδονίδων<br>ἆγε βαρὺ κλαίοισα, θεὰ δ’ ἐλέησεν ἑταίραν<br>καί νιν Ἀθαναία πρὸς τόδ’ ἔλεξεν ἔπος<br>‘δῖα γύναι μετὰ πάντα βαλεῦ πάλιν ὅσσα δι’ ὀργάν<br>εἶπας· ἐγὼ δ’ οὔ τοι τέκνον ἔθηκ’ ἀλαόν.<br>οὐ γὰρ Ἀθαναίαι γλυκερὸν πέλει ὄμματα παίδων<br>ἁρπάζειν· Κρόνιοι δ’ ὧδε λέγοντι νόμοι·<br>ὅς κε τιν’ ἀθανάτων, ὅκα μὴ θεὸς αὐτὸς ἕληται,<br>ἀθρήσηι, μισθῶ τοῦτον ἰδεῖν μεγάλω.<br>δῖα γύναι, τὸ μὲν οὐ παλινάγρετον αὖθι γένοιτο<br>ἔργον· ἐπεὶ μοιρᾶν ὧδ’ ἐπένησε λίνα,<br>ἁνίκα τὸ πρᾶτόν νιν ἐγείναο· νῦν δὲ κομίζευ,<br>ὦ Εὐηρείδα, τέλθος ὀφειλόμενον.<br>πόσσα μὲν ἁ Καδμηὶς ἐς ὕστερον ἔμπυρα καυσεῖ,<br>πόσσα δ’ Ἀρισταῖος, τὸν μόνον εὐχόμενοι<br>παῖδα, τὸν ἁβατὰν Ἀκταίονα, τυφλὸν ἰδέσθαι.<br>καὶ τῆνος μεγάλας σύνδρομος Ἀρτέμιδος<br>ἐσσεῖτ’· ἀλλ’ οὐκ αὐτὸν ὅ τε δρόμος αἵ τ’ ἐν ὄρεσσι<br>ῥυσεῦνται ξυναὶ τᾶμος ἑκαβολίαι,<br>ὁππόκα κοὐκ ἐθέλων περ ἴδηι χαρίεντα λοετρά<br>δαίμονος· ἀλλ’ αὐταὶ τὸν πρὶν ἄνακτα κύνες<br>τουτάκι δειπνησεῦντι· τὰ δ’ υἱέος ὀστέα μάτηρ<br>λεξεῖται δρυμὼς πάντας ἐπερχομένα·<br>ὀλβίσταν ἐρέει σε καὶ εὐαίωνα γενέσθαι,<br>ἐξ ὀρέων ἀλαὸν παῖδ’ ἀποδεξαμέναν.", "st": "H5"}, {"sp": "N", "t": "ὦ ἑτάρα, τῶι μή τι μινύρεο· τῶιδε γὰρ ἄλλα<br>τεῦ χάριν ἐξ ἐμέθεν πολλὰ μενεῦντι γέρα.<br>μάντιν ἐπεὶ θησῶ νιν ἀοίδιμον ἐσσομένοισιν,<br>ἦ μέγα τῶν ἄλλων δή τι περισσότερον,<br>γνωσεῖται δ’ ὄρνιχας, ὃς αἴσιος οἵ τε πέτονται<br>ἤλιθα καὶ ποίων οὐκ ἀγαθαὶ πτέρυγες.<br>πολλὰ δὲ Βοιωτοῖσι θεοπρόπα, πολλὰ δὲ Κάδμωι<br>χρησεῖ, καὶ μεγάλοις ὕστερα Λαβδακίδαις.<br>δωσῶ καὶ μέγα βάκτρον, ὅ οἱ πόδας ἐς δέον ἀξεῖ,<br>δωσῶ καὶ βιότω τέρμα πολυχρόνιον.<br>καὶ μόνος, εὖτε θάνηι, πεπνυμένος ἐν νεκύεσσι<br>φοιτασεῖ, μεγάλωι τίμιος Ἁγεσίλαι.’<br>ὣς φαμένα κατένευσε· τὸ δ’ ἐντελές ὧι κ’ ἔπι νεύσηι<br>Παλλάς, ἐπεὶ μώναι Ζεὺς τό γε θυγατέρων<br>δῶκεν Ἀθαναίαι, πατρώια πάντα φέρεσθαι,<br>λωτροχόοι, μάτηρ δ’ οὔτις ἔτικτε θεάν,<br>ἀλλὰ Διὸς κορυφά. κορυφὰ Διὸς οὐκ ἐπινεύει<br>ψεύδεα … αι θυγάτηρ.<br>ἔρχετ’ Ἀθαναία νῦν ἀτρεκές· ἀλλὰ δέχεσθε<br>τὰν θεόν, ὦ κῶραι, τὦργον ὅσαις μέλεται,<br>σύν τ’ εὐαγορίαι σύν τ’ εὔγμασι σύν τ’ ὀλολυγαῖς.<br>χαῖρε θεά, κάδευ δ’ Ἄργεος Ἰναχίω.<br>χαῖρε καὶ ἐξελάοισα, καὶ ἐς πάλιν αὖτις ἐλάσσαις<br>ἵππως, καὶ Δαναῶν κλᾶρον ἅπαντα σάω.", "st": "H5"}, {"sp": "SEC", "t": "Εἰς Δήμητρα", "st": "H6"}, {"sp": "N", "t": "τῶ καλάθω κατιόντος ἐπιφθέγξασθε γυναῖκες<br>‘Δάματερ μέγα χαῖρε πολύτροφε πουλυμέδιμνε’.<br>τὸν κάλαθον κατιόντα χαμαὶ θασεῖσθε βέβαλοι,<br>μηδ’ ἀπὸ τῶ τέγεος μηδ’ ὑψόθεν αὐγάσσησθε<br>μὴ παῖς μηδὲ γυνὰ μηδ’ ἃ κατεχεύατο χαίταν,<br>μηδ’ ὅκ’ ἀφ’ αὑαλέων στομάτων πτύωμες ἄπαστοι.<br>ἕσπερος ἐκ νεφέων ἐσκέψατο (πανίκα νεῖται;),<br>ἕσπερος, ὅστε πιεῖν Δαμάτερα μῶνος ἔπεισεν,<br>ἁρπαγίμας ὅκ’ ἄπυστα μετέστιχεν ἴχνια κώρας.<br>πότνια πῶς σε δύναντο πόδες φέρεν ἔστ’ ἐπὶ δυθμάς,<br>ἔστ’ ἐπὶ τὼς μέλανας καὶ ὅπα τὰ χρύσεα μᾶλα;<br>οὐ πίες οὐδ’ ἄρ’ ἔδες τῆνον χρόνον οὐδὲ λοέσσα.<br>τρὶς μὲν δὴ διέβας Ἀχελώιον ἀργυροδίναν,<br>τοσσάκι δ’ ἀενάων ποταμῶν ἐπέρασας ἕκαστον,<br>τρὶς δ’ ἐπὶ Καλλιχόρωι χαμάδις ἐκαθίσσαο φρητί<br>αὐσταλέα ἄποτός τε καὶ οὐ φάγες οὐδὲ λοέσσα.<br>μὴ μὴ ταῦτα λέγωμες ἃ δάκρυον ἄγαγε Δηοῖ·<br>κάλλιον, ὡς πολίεσσιν ἑαδότα τέθμια δῶκε·<br>κάλλιον, ὡς καλάμαν τε καὶ ἱερὰ δράγματα πράτα<br>ἀσταχύων ἀπέκοψε καὶ ἐν βόας ἧκε πατῆσαι,<br>ἁνίκα Τριπτόλεμος ἀγαθὰν ἐδιδάσκετο τέχναν·", "st": "H6"}, {"sp": "N", "t": "κάλλιον, ὡς (ἵνα καί τις ὑπερβασίας ἀλέηται)<br>π …<br>οὔπω τὰν Κνιδίαν, ἔτι Δώτιον ἱρὸν ἔναιον,<br>τεῖ δ’ αὐτᾶι καλὸν ἄλσος ἐποιήσαντο Πελασγοί<br>δένδρεσιν ἀμφιλαφές· διά κεν μόλις ἦνθεν ὀιστός·<br>ἐν πίτυς, ἐν μεγάλαι πτελέαι ἔσαν, ἐν δὲ καὶ ὄχναι,<br>ἐν δὲ καλὰ γλυκύμαλα· τὸ δ’ ὥστ’ ἀλέκτρινον ὕδωρ<br>ἐξ ἀμαρᾶν ἀνέθυε. θεὰ δ’ ἐπεμαίνετο χώρωι<br>ὅσσον Ἐλευσῖνι, Τριόπαι θ’ ὅσον ὁκκόσον Ἔνναι.<br>ἀλλ’ ὅκα Τριοπίδαισιν ὁ δεξιὸς ἄχθετο δαίμων,<br>τουτάκις ἁ χείρων Ἐρυσίχθονος ἅψατο βωλά·<br>σεύατ’ ἔχων θεράποντας ἐείκοσι, πάντας ἐν ἀκμᾶι,<br>πάντας δ’ ἀνδρογίγαντας ὅλαν πόλιν ἀρκίος ἆραι,<br>ἀμφότερον πελέκεσσι καὶ ἀξίναισιν ὁπλίσσας<br>ἐς δὲ τὸ τᾶς Δάματρος ἀναιδέες ἔδραμον ἄλσος.<br>ἦς δέ τις αἴγειρος, μέγα δένδρεον αἰθέρι κῦρον,<br>τῶι ἔπι ταὶ νύμφαι ποτὶ τὤνδιον ἑψιόωντο,<br>ἃ πράτα πλαγεῖσα κακὸν μέλος ἴαχεν ἄλλαις.<br>ἄισθετο Δαμάτηρ ὅτι οἱ ξύλον ἱερὸν ἄλγει,<br>εἶπε δὲ χωσαμένα ‘τίς μοι καλὰ δένδρεα κόπτει;’<br>αὐτίκα Νικίππαι, τὰν οἱ πόλις ἀράτειραν<br>δαμοσίαν ἔστασαν, ἐείσατο, γέντο δὲ χειρί<br>στέμματα καὶ μάκωνα, κατωμαδίαν δ’ ἔχε κλαῖδα.", "st": "H6"}, {"sp": "N", "t": "φᾶ δὲ παραψύχοισα κακὸν καὶ ἀναιδέα φῶτα<br>‘τέκνον, ὅτις τὰ θεοῖσιν ἀνειμένα δένδρεα κόπτεις,<br>τέκνον ἐλίνυσον, τέκνον πολύθεστε τοκεῦσι,<br>παύεο καὶ θεράποντας ἀπότρεπε, μή τι χαλεφθῆι<br>πότνια Δαμάτηρ, τᾶς ἱερὸν ἐκκεραΐζεις’.<br>τὰν δ’ ἄρ’ ὑποβλέψας χαλεπώτερον ἠὲ κυναγὸν<br>ὤρεσιν ἐν Τμαρίοισιν ὑποβλέπει ἄνδρα λέαινα<br>ὠμοτόκος, τᾶς φαντὶ πέλειν βλοσυρώτατον ὄμμα,<br>‘χάζευ’ ἔφα ‘μή τοι πέλεκυν μέγαν ἐν χροῒ παξῶ.<br>ταῦτα δ’ ἐμὸν θησεῖ στεγανὸν δόμον, ὧι ἔνι δαῖτας<br>αἰὲν ἐμοῖς ἑτάροισιν ἄδην θυμαρέας ἀξῶ.’<br>εἶπεν ὁ παῖς, Νέμεσις δὲ κακὰν ἐγράψατο φωνάν.<br>Δαμάτηρ δ’ ἄφατόν τι κοτέσσατο, εἴσατο δ’ ἁ θεύς·<br>ἴθματα μὲν χέρσω, κεφαλὰ δέ οἱ ἅψατ’ Ὀλύμπω.<br>οἳ μὲν ἄρ’ ἡμιθνῆτες, ἐπεὶ τὰν πότνιαν εἶδον,<br>ἐξαπίνας ἀπόρουσαν ἐνὶ δρυσὶ χαλκὸν ἀφέντες.<br>ἃ δ’ ἄλλως μὲν ἔασεν, ἀναγκαίαι γὰρ ἕποντο<br>δεσποτικὰν ὑπὸ χεῖρα, βαρὺν δ’ ἀπαμείψατ’ ἄνακτα<br>‘ναὶ ναί, τεύχεο δῶμα κύον κύον ὧι ἔνι δαῖτας<br>ποιησεῖς· θαμιναὶ γὰρ ἐς ὕστερον εἰλαπίναι τοι.’<br>ἃ μὲν τόσσ’ εἰποῖσ’ Ἐρυσίχθονι τεῦχε πονηρά.", "st": "H6"}, {"sp": "N", "t": "αὐτίκα οἱ χαλεπόν τε καὶ ἄγριον ἔμβαλε λιμόν<br>αἴθωνα κρατερόν, μεγάλαι δ’ ἐστρεύγετο νούσωι.<br>σχέτλιος, ὅσσα πάσαιτο τόσων ἔχεν ἵμερος αὖτις.<br>εἴκατι δαῖτα πένοντο, δυώδεκα δ’ οἶνον ἄφυσσον·<br>τόσσα Διώνυσον γὰρ ἃ καὶ Δάματρα χαλέπτει·<br>† καὶ γὰρ τᾶι Δάματρι συνωργίσθη Διόνυσος.<br>οὔτε νιν εἰς ἐράνως οὔτε ξυνδείπνια πέμπον<br>αἰδόμενοι γονέες, προχανὰ δ’ εὑρίσκετο πᾶσα.<br>ἦνθον Ἰτωνιάδος νιν Ἀθαναίας ἐπ’ ἄεθλα<br>Ὀρμενίδαι καλέοντες· ἀπ’ ὦν ἀρνήσατο μάτηρ<br>‘οὐκ ἔνδοι, χθιζὸς γὰρ ἐπὶ Κραννῶνα βέβακε<br>τέλθος ἀπαιτησῶν ἑκατὸν βόας’. ἦνθε Πολυξώ,<br>μάτηρ Ἀκτορίωνος, ἐπεὶ γάμον ἄρτυε παιδί,<br>ἀμφότερον Τριόπαν τε καὶ υἱέα κικλήσκοισα.<br>τὰν δὲ γυνὰ βαρύθυμος ἀμείβετο δάκρυ χέοισα<br>‘νεῖταί τοι Τριόπας, Ἐρυσίχθονα δ’ ἤλασε κάπρος<br>Πίνδον ἀν’ εὐάγκειαν, ὃ δ’ ἐννέα φάεα κεῖται’.<br>δειλαία φιλότεκνε, τί δ’ οὐκ ἐψεύσαο, μᾶτερ;", "st": "H6"}, {"sp": "N", "t": "δαίνυεν εἰλαπίναν τις· ‘ἐν ἀλλοτρίοις Ἐρυσίχθων’.<br>ἄγετό τις νύμφαν· ‘Ἐρυσίχθονα δίσκος ἔτυψεν,’<br>ἢ ‘ἔπεσ’ ἐξ ἵππων’, ἢ ‘ἐν Ὄθρυϊ ποίμνι’ ἀμιθρεῖ’.<br>ἐνδόμυχος δἤπειτα πανάμερος εἰλαπιναστάς<br>ἤσθιε μυρία πάντα· κακὰ δ’ ἐξάλλετο γαστήρ<br>αἰεὶ μᾶλλον ἔδοντι, τὰ δ’ ἐς βυθὸν οἷα θαλάσσας<br>ἀλεμάτως ἀχάριστα κατέρρεεν εἴδατα πάντα.<br>ὡς δὲ Μίμαντι χιών, ὡς ἀελίωι ἔνι πλαγγών,<br>καὶ τούτων † ἔτι μεῖζον ἐτάκετο μέσφ’ ἐπὶ νευράς·<br>δειλαίωι ἶνές τε καὶ ὀστέα μῶνον ἔλειφθεν.<br>κλαῖε μὲν ἁ μάτηρ, βαρὺ δ’ ἔστενον αἱ δύ’ ἀδελφαί<br>χὡ μαστὸς τὸν ἔπωνε καὶ αἱ δέκα πολλάκι δῶλαι.<br>καὶ δ’ αὐτὸς Τριόπας πολιαῖς ἐπὶ χεῖρας ἔβαλλε,<br>τοῖα τὸν οὐκ ἀίοντα Ποσειδάωνα καλιστρέων·<br>‘ψευδοπάτωρ ἰδὲ τόνδε τεοῦ τρίτον, εἴπερ ἐγὼ μέν<br>σεῦ τε καὶ Αἰολίδος Κανάκας γένος, αὐτὰρ ἐμεῖο<br>τοῦτο τὸ δείλαιον γένετο βρέφος· αἴθε γὰρ αὐτόν<br>βλητὸν ὑπ’ Ἀπόλλωνος ἐμαὶ χέρες ἐκτερέιξαν·<br>νῦν δὲ κακὰ βούβρωστις ἐν ὀφθαλμοῖσι κάθηται.", "st": "H6"}, {"sp": "N", "t": "ἤ οἱ ἀπόστασον χαλεπὰν νόσον ἠέ νιν αὐτός<br>βόσκε λαβών· ἁμαὶ γὰρ ἀπειρήκαντι τράπεζαι.<br>χῆραι μὲν μάνδραι, κενεαὶ δέ μοι αὔλιες ἤδη<br>τετραπόδων, ἤδη γὰρ ἀπαρνήσαντο μάγειροι.’<br>ἀλλὰ καὶ οὐρῆας μεγαλᾶν ὑπέλυσαν ἁμαξᾶν,<br>καὶ τὰν βῶν ἔφαγεν, τὰν Ἑστίαι ἔτρεφε μάτηρ,<br>καὶ τὸν ἀεθλοφόρον καὶ τὸν πολεμήιον ἵππον,<br>καὶ τὰν αἴλουρον, τὰν ἔτρεμε θηρία μικκά.<br>μέσφ’ ὅκα μὲν Τριόπαο δόμοις ἔνι χρήματα κεῖτο,<br>μῶνοι ἄρ’ οἰκεῖοι θάλαμοι κακὸν ἠπίσταντο.<br>ἀλλ’ ὅκα τὸν βαθὺν οἶκον ἀνεξήραναν ὀδόντες,<br>καὶ τόχ’ ὁ τῶ βασιλῆος ἐνὶ τριόδοισι καθῆστο<br>αἰτίζων ἀκόλως τε καὶ ἔκβολα λύματα δαιτός.<br>Δάματερ, μὴ τῆνος ἐμὶν φίλος, ὅς τοι ἀπεχθής,<br>εἴη μηδ’ ὁμότοιχος· ἐμοὶ κακογείτονες ἐχθροί.<br>ἄισατε παρθενικαί, καὶ ἐπιφθέγξασθε τεκοῖσαι<br>‘Δάματερ μέγα χαῖρε πολύτροφε πουλυμέδιμνε’.", "st": "H6"}, {"sp": "N", "t": "χὠς αἱ τὸν κάλαθον λευκότριχες ἵπποι ἄγοντι<br>τέσσαρες, ὣς ἁμὶν μεγάλα θεὸς εὐρυάνασσα<br>λευκὸν ἔαρ, λευκὸν δὲ θέρος καὶ χεῖμα φέροισα<br>ἡξεῖ καὶ φθινόπωρον, ἔτος δ’ εἰς ἄλλο φυλαξεῖ.<br>ὡς δ’ ἀπεδίλωτοι καὶ ἀνάμπυκες ἄστυ πατεῦμες,<br>ὣς πόδας, ὣς κεφαλὰς παναπηρέας ἕξομες αἰεί.<br>ὡς δ’ αἱ λικνοφόροι χρυσῶ πλέα λίκνα φέροντι,<br>ὣς ἁμὲς τὸν χρυσὸν ἀφειδέα πασαίμεσθα.<br>μέσφα τὰ τᾶς πόλιος πρυτανήια τὰς ἀτελέστως,<br>τὰς δὲ τελεσφορέας ποτὶ τὰν θεὸν ἄχρις ὁμαρτεῖν,<br>αἵτινες ἑξήκοντα κατώτεραι· αἱ δὲ βαρεῖαι<br>χἄτις Ἐλειθυίαι τείνει χέρα χἄτις ἐν ἄλγει,<br>ὣς ἅλις, ὡς αὐτᾶν ἱκανὸν γόνυ· ταῖσι δὲ Δηώ<br>δωσεῖ πάντ’ ἐπίμεστα καὶ ὡς ποτὶ ναὸν ἵκωνται.<br>χαῖρε θεὰ καὶ τάνδε σάω πόλιν ἔν θ’ ὁμονοίαι<br>ἔν τ’ εὐηπελίαι, φέρε δ’ ἀγρόθι νόστιμα πάντα·<br>φέρβε βόας, φέρε μᾶλα, φέρε στάχυν, οἶσε θερισμόν,<br>φέρβε καὶ εἰράναν, ἵν’ ὃς ἄροσε τῆνος ἀμάσηι.<br>ἵλαθί μοι τρίλλιστε μέγα κρείοισα θεάων.", "st": "H6"}, {"sp": "SEC", "t": "Ἐπιγράμματα", "st": "E.1"}, {"sp": "N", "t": "ξεῖνος Ἀταρνείτης τις ἀνήρετο Πιττακὸν οὕτω<br>τὸν Μυτιληναῖον, παῖδα τὸν Ὑρράδιον·<br>‘ἄττα γέρον, δοιός με καλεῖ γάμος· ἡ μία μὲν δή<br>νύμφη καὶ πλούτωι καὶ γενεῆι κατ’ ἐμέ,<br>ἡ δ’ ἑτέρη προβέβηκε· τί λώιον; εἰ δ’ ἄγε σύμ μοι<br>βούλευσον, ποτέρην εἰς ὑμέναιον ἄγω.’<br>εἶπεν· ὁ δὲ σκίπωνα, γεροντικὸν ὅπλον, ἀείρας,<br>‘ἠνίδε, κεῖνοί τοι πᾶν ἐρέουσιν ἔπος.’<br>οἳ δ’ ἄρ’ ὑπὸ πληγῆισι θοὰς βέμβικας ἔχοντες<br>ἔστρεφον εὐρείηι παῖδες ἐνὶ τριόδωι.<br>‘κείνων ἔρχεο’ φησὶ ‘μετ’ ἴχνια’. χὠ μὲν ἐπέστη<br>πλησίον· οἳ δ’ ἔλεγον· ‘τὴν κατὰ σαυτὸν ἔλα’.<br>ταῦτ’ ἀίων ὁ ξεῖνος ἐφείσατο μείζονος οἴκου<br>δράξασθαι παίδων κληδόνι συνθέμενος.<br>τὴν δ’ ὀλίγην ὡς κεῖνος ἐς οἰκίον ἤγετο νύμφην,<br>οὕτω καὶ σύ, Δίων, τὴν κατὰ σαυτὸν ἔλα.", "st": "E.1"}, {"sp": "N", "t": "εἶπέ τις Ἡράκλειτε τεὸν μόρον, ἐς δέ με δάκρυ<br>ἤγαγεν, ἐμνήσθην δ’ ὁσσάκις ἀμφότεροι<br>ἥλιον ἐν λέσχηι κατεδύσαμεν· ἀλλὰ σὺ μέν που<br>ξεῖν’ Ἁλικαρνησεῦ τετράπαλαι σποδιή·<br>αἱ δὲ τεαὶ ζώουσιν ἀηδόνες, ἧισιν ὁ πάντων<br>ἁρπακτὴς Ἀίδης οὐκ ἐπὶ χεῖρα βαλεῖ.", "st": "E.2"}, {"sp": "N", "t": "Τίμων μισάνθρωπος ἐνοικέω. ἀλλὰ πάρελθε<br>οἰμώζειν εἴπας πολλά, πάρελθε μόνον.", "st": "E.III"}, {"sp": "N", "t": "μὴ χαίρειν εἴπῃς με, κακὸν κέαρ, ἀλλὰ πάρελθε·<br>ἶσον ἐμοὶ χαίρειν ἐστὶ τὸ μὴ σὲ γελᾶν.", "st": "E.3"}, {"sp": "N", "t": "Τίμων, οὐ γὰρ ἔτ’ ἐσσί, τί τοι, σκότος ἢ φάος ἐχθρόν;<br>‘τὸ σκότος· ὑμέων γὰρ πλείονες εἰν Ἀίδηι’.", "st": "E.4"}, {"sp": "N", "t": "κόγχος ἐγὼ Ζεφυρῖτι πάλαι τέρας· ἀλλὰ σὺ νῦν με<br>Κύπρι Σεληναίης ἄνθεμα πρῶτον ἔχεις,<br>ναυτίλος ὃς πελάγεσσιν ἐπέπλεον, εἰ μὲν ἀῆται,<br>τείνας οἰκείων λαῖφος ἀπὸ προτόνων,<br>εἰ δὲ Γαληναίη, λιπαρὴ θεός, οὖλος ἐρέσσων<br>ποσσί νιν, ὥστ’ ἔργωι τοὔνομα συμφέρεται,<br>ἔστ’ ἔπεσον παρὰ θῖνας Ἰουλίδας, ὄφρα γένωμαι<br>σοὶ τὸ περίσκεπτον παίγνιον, Ἀρσινόη,<br>μηδέ μοι ἐν θαλάμηισιν ἔθ’ ὡς πάρος, εἰμὶ γὰρ ἄπνους,<br>τίκτηται νοτερῆισ’ ὤεον ἁλκυονίς.<br>Κλεινίου ἀλλὰ θυγατρὶ δίδου χάριν, οἶδε γὰρ ἐσθλά<br>ῥέζειν καὶ Σμύρνης ἐστὶν ἀπ’ Αἰολίδος.", "st": "E.5"}, {"sp": "N", "t": "τοῦ Σαμίου πόνος εἰμὶ δόμωι ποτὲ θεῖον ἀοιδόν<br>δεξαμένου, κλείω δ’ Εὔρυτον, ὅσσ’ ἔπαθεν,<br>καὶ ξανθὴν Ἰόλειαν, Ὁμήρειον δὲ καλεῦμαι<br>γράμμα· Κρεωφύλωι, Ζεῦ φίλε, τοῦτο μέγα.", "st": "E.6"}, {"sp": "N", "t": "στήλην μητρυιῆς, μικρὰν λίθον, ἔστεφε κοῦρος,<br>ὡς βίον ἠλλάχθαι καὶ τρόπον οἰόμενος·<br>ἡ δὲ τάφῳ κλινθέντα κατέκτανε παῖδα πεσοῦσα·<br>φεύγετε μητρυιῆς καὶ τάφον οἱ πρόγονοι.", "st": "E.VII"}, {"sp": "N", "t": "ἦλθε Θεαίτητος καθαρὴν ὁδόν. εἰ δ’ ἐπὶ κισσόν<br>τὸν τεὸν οὐχ αὕτη, Βάκχε, κέλευθος ἄγει·<br>ἄλλων μὲν κήρυκες ἐπὶ βραχὺν οὔνομα καιρόν<br>φθέγξονται, κείνου δ’ Ἑλλὰς ἀεὶ σοφίην.", "st": "E.7"}, {"sp": "N", "t": "μικρή τις Διόνυσε καλὰ πρήσσοντι ποιητῆι<br>ῥῆσις· ὃ μὲν ‘νικῶ’ φησὶ τὸ μακρότατον,<br>ὧι δὲ σὺ μὴ πνεύσηις ἐπιδέξιος, ἤν τις ἔρηται<br>‘πῶς ἔβαλες’; φησί ‘σκληρὰ τὰ γιγνόμενα’.<br>τῶι μερμηρίξαντι τὰ μὴ ’νδικα τοῦτο γένοιτο<br>τοὖπος· ἐμοὶ δ’, ὦναξ, ἡ βραχυσυλλαβίη.", "st": "E.8"}, {"sp": "N", "t": "Τῆιδε Σάων ὁ Δίκωνος Ἀκάνθιος ἱερὸν ὕπνον<br>κοιμᾶται· θνήισκειν μὴ λέγε τοὺς ἀγαθούς.", "st": "E.9"}, {"sp": "N", "t": "Ἢν δίζηι Τίμαρχον ἐν Ἄιδος, ὄφρα πύθηαι<br>ἤ τι περὶ ψυχῆς ἢ πάλι πῶς ἔσεαι,<br>δίζησθαι φυλῆς Πτολεμαίδος υἱέα πατρός<br>Παυσανίου· δήεις δ’ αὐτὸν ἐν εὐσεβέων.", "st": "E.10"}, {"sp": "N", "t": "σύντομος ἦν ὁ ξεῖνος, ὃ καὶ στίχος οὐ μακρὰ λέξων<br>‘Θῆρις Ἀρισταίου Κρής’ ἐπ’ ἐμοὶ δολιχός.", "st": "E.11"}, {"sp": "N", "t": "Κύζικον ἢν ἔλθηις, ὀλίγος πόνος Ἱππακὸν εὑρεῖν<br>καὶ Διδύμην· ἀφανὴς οὔ τι γὰρ ἡ γενεή.<br>καί σφιν ἀνιηρὸν μὲν ἐρεῖς ἔπος, ἔμπα δὲ λέξαι<br>τοῦθ’, ὅτι τὸν κείνων ὧδ’ ἐπέχω Κριτίην.", "st": "E.12"}, {"sp": "N", "t": "Ἦ ῥ’ ὑπὸ σοὶ Χαρίδας ἀναπαύεται; ‘εἰ τὸν Ἀρίμμα<br>τοῦ Κυρηναίου παῖδα λέγεις, ὑπ’ ἐμοί.’<br>ὦ Χαρίδα, τί τὰ νέρθε; ‘πολὺ σκότος’. αἱ δ’ ἄνοδοι τί;<br>‘ψεῦδος’. ὁ δὲ Πλούτων; ‘μῦθος’. ἀπωλόμεθα.<br>‘οὗτος ἐμὸς λόγος ὔμμιν ἀληθινός· εἰ δὲ τὸν ἡδύν<br>βούλει, Πελλαίου βοῦς μέγας εἰν Ἀίδηι.’", "st": "E.13"}, {"sp": "N", "t": "δαίμονα τίς δ’ εὖ οἶδε τὸν Αὔριον; ἁνίκα καὶ σέ<br>Χάρμι τὸν ὀφθαλμοῖς χθιζὸν ἐν ἁμετέροις<br>τᾶι ἑτέραι κλαύσαντες ἐθάπτομεν· οὐδὲν ἐκείνου<br>εἶδε πατὴρ Διοφῶν χρῆμ’ ἀνιαρότερον.", "st": "E.14"}, {"sp": "N", "t": "‘Τιμονόη.’ τίς δ’ ἐσσί; μὰ δαίμονας, οὔ σ’ ἂν ἐπέγνων,<br>εἰ μὴ Τιμοθέου πατρὸς ἐπῆν ὄνομα<br>στήληι καὶ Μήθυμνα, τεὴ πόλις. ἦ μέγα φημί<br>χῆρον ἀνιᾶσθαι σὸν πόσιν Εὐθυμένη.", "st": "E.15"}, {"sp": "N", "t": "Κρηθίδα τὴν πολύμυθον ἐπισταμένην καλὰ παίζειν<br>δίζηνται Σαμίων πολλάκι θυγατέρες,<br>ἡδίστην συνέριθον ἀεὶ λάλον· ἣ δ’ ἀποβρίζει<br>ἐνθάδε τὸν πάσαις ὕπνον ὀφειλόμενον.", "st": "E.16"}, {"sp": "N", "t": "ὤφελε μηδ’ ἐγένοντο θοαὶ νέες· οὐ γὰρ ἂν ἡμεῖς<br>παῖδα Διοκλείδου Σώπολιν ἐστένομεν.<br>νῦν δ’ ὃ μὲν εἰν ἁλί που φέρεται νέκυς, ἀντὶ δ’ ἐκείνου<br>οὔνομα καὶ κενεὸν σῆμα παρερχόμεθα.", "st": "E.17"}, {"sp": "N", "t": "Νάξιος οὐκ ἐπὶ γῆς ἔθανεν Λύκος, ἀλλ’ ἐνὶ πόντωι<br>ναῦν ἅμα καὶ ψυχὴν εἶδεν ἀπολλυμένην,<br>ἔμπορος Αἰγίνηθεν ὅτ’ ἔπλεε. χὢ μὲν ἐν ὑγρῆι<br>νεκρός, ἐγὼ δ’ ἄλλως οὔνομα τύμβος ἔχων<br>κηρύσσω πανάληθες ἔπος τόδε ‘φεῦγε θαλάσσηι<br>συμμίσγειν ἐρίφων ναυτίλε δυομένων’.", "st": "E.18"}, {"sp": "N", "t": "Δωδεκέτη τὸν παῖδα πατὴρ ἀπέθηκε Φίλιππος<br>ἐνθάδε τὴν πολλὴν ἐλπίδα Νικοτέλην.", "st": "E.19"}, {"sp": "N", "t": "Ἠῶιοι Μελάνιππον ἐθάπτομεν, ἠελίου δέ<br>δυομένου Βασιλὼ κάτθανε παρθενική<br>αὐτοχερί· ζώειν γὰρ ἀδελφεὸν ἐν πυρὶ θεῖσα<br>οὐκ ἔτλη. δίδυμον δ’ οἶκος ἐπεῖδε κακόν<br>πατρὸς Ἀριστίπποιο, κατήφησεν δὲ Κυρήνη<br>πᾶσα τὸν εὔτεκνον χῆρον ἰδοῦσα δόμον.", "st": "E.20"}, {"sp": "N", "t": "Ὅστις ἐμὸν παρὰ σῆμα φέρεις πόδα, Καλλιμάχου με<br>ἴσθι Κυρηναίου παῖδά τε καὶ γενέτην.<br>εἰδείης δ’ ἄμφω κεν· ὃ μέν κοτε πατρίδος ὅπλων<br>ἦρξεν, ὃ δ’ ἤεισεν κρέσσονα βασκανίης·<br>οὐ νέμεσις· Μοῦσαι γὰρ ὅσους ἴδον ὄμματι παῖδας<br>μὴ λοξῶι, πολιοὺς οὐκ ἀπέθεντο φίλους.<br>…", "st": "E.21"}, {"sp": "N", "t": "Ἀστακίδην τὸν Κρῆτα τὸν αἰπόλον ἥρπασε Νύμφη<br>ἐξ ὄρεος, καὶ νῦν ἱερὸς Ἀστακίδης.<br>οὐκέτι Δικταίηισιν ὑπὸ δρυσίν, οὐκέτι Δάφνιν<br>ποιμένες, Ἀστακίδην δ’ αἰὲν ἀεισόμεθα.", "st": "E.22"}, {"sp": "N", "t": "εἴπας ‘Ἥλιε χαῖρε’ Κλεόμβροτος Ὡμβρακιώτης<br>ἥλατ’ ἀφ’ ὑψηλοῦ τείχεος εἰς Ἀίδην,<br>ἄξιον οὐδὲν ἰδὼν θανάτου κακόν, ἀλλὰ Πλάτωνος<br>ἓν τὸ περὶ ψυχῆς γράμμ’ ἀναλεξάμενος.", "st": "E.23"}, {"sp": "N", "t": "Ἥρως Αἰετίωνος ἐπίσταθμος Ἀμφιπολίτεω<br>ἵδρυμαι μικρῶι μικρὸς ἐπὶ προθύρωι<br>λοξὸν ὄφιν καὶ μοῦνον ἔχων ξίφος· ἀνδρὶ † ιπειωι<br>θυμωθεὶς πεζὸν κἀμὲ παρωικίσατο.", "st": "E.24"}, {"sp": "N", "t": "ὤμοσε Καλλίγνωτος Ἰωνίδι μήποτ’ ἐκείνης<br>ἕξειν μήτε φίλον κρέσσονα μήτε φίλην.<br>ὤμοσεν· ἀλλὰ λέγουσιν ἀληθέα τοὺς ἐν ἔρωτι<br>ὅρκους μὴ δύνειν οὔατ’ ἐς ἀθανάτων.<br>νῦν δ’ ὃ μὲν ἀρσενικῶι θέρεται πυρί· τῆς δὲ ταλαίνης<br>νύμφης ὡς Μεγαρέων οὐ λόγος οὐδ’ ἀριθμός.", "st": "E.25"}, {"sp": "N", "t": "…", "st": "E.XXVII"}, {"sp": "N", "t": "εἶχον ἀπὸ σμικρῶν ὀλίγον βίον οὔτε τι δεινόν<br>ῥέζων οὔτ’ ἀδικέων οὐδένα. γαῖα φίλη,<br>Μικύλος εἴ τι πονηρὸν ἐπήινεσα, μήτε σὺ κούφη<br>γίνεο μήθ’ ἵλεω δαίμονες οἵ μ’ ἔχετε.", "st": "E.26"}, {"sp": "N", "t": "Ἡσιόδου τό τ’ ἄεισμα καὶ ὁ τρόπος· οὐ τὸν ἀοιδόν<br>ἔσχατον, ἀλλ’ ὀκνέω μὴ τὸ μελιχρότατον<br>τῶν ἐπέων ὁ Σολεὺς ἀπεμάξατο· χαίρετε λεπταί<br>ῥήσιες, Ἀρήτου σύμβολον ἀγρυπνίης.", "st": "E.27"}, {"sp": "N", "t": "ἐχθαίρω τὸ ποίημα τὸ κυκλικόν, οὐδὲ κελεύθωι<br>χαίρω τίς πολλοὺς ὧδε καὶ ὧδε φέρει,<br>μισέω καὶ περίφοιτον ἐρώμενον, οὐδ’ ἀπὸ κρήνης<br>πίνω· σικχαίνω πάντα τὰ δημόσια.<br>Λυσανίη σὺ δὲ ναιχὶ καλὸς καλός — ἀλλὰ πρὶν εἰπεῖν<br>τοῦτο σαφῶς, Ἠχώ φησί τις ‘ἄλλος ἔχει’.", "st": "E.28"}, {"sp": "N", "t": "ἔγχει καὶ πάλιν εἰπὲ ‘Διοκλέος’. οὐδ’ Ἀχελῶιος<br>κείνου τῶν ἱερῶν αἰσθάνεται κυάθων.<br>καλὸς ὁ παῖς Ἀχελῶιε λίην καλός, εἰ δέ τις οὐχί<br>φησίν — ἐπισταίμην μοῦνος ἐγὼ τὰ καλά.", "st": "E.29"}, {"sp": "N", "t": "Θεσσαλικὲ Κλεόνικε τάλαν, τάλαν, οὐ μὰ τὸν ὀξύν<br>ἥλιον, οὐκ ἔγνων· σχέτλιε ποῦ γέγονας;<br>ὀστέα σοὶ καὶ μοῦνον ἔτι τρίχες· ἦ ῥά σε δαίμων<br>οὑμὸς ἔχει, χαλεπῆι δ’ ἤντεο θευμορίηι;<br>ἔγνων· Εὐξίθεός σε συνήρπασε, καὶ σὺ γὰρ ἐλθών<br>τὸν καλόν, ὦ μοχθήρ’, ἔβλεπες ἀμφοτέροις.", "st": "E.30"}, {"sp": "N", "t": "Ὡγρευτὴς Ἐπίκυδες ἐν οὔρεσι πάντα λαγωόν<br>διφᾶι καὶ πάσης ἴχνια δορκαλίδος<br>στείβηι καὶ νιφετῶι κεχαρημένος, ἢν δέ τις εἴπηι<br>‘τῆ, τόδε βέβληται θηρίον’ οὐκ ἔλαβεν.<br>χοὐμὸς ἔρως τοιόσδε· τὰ γὰρ φεύγοντα διώκειν<br>οἶδε, τὰ δ’ ἐν μέσσωι κείμενα παρπέτεται.", "st": "E.31"}, {"sp": "N", "t": "οἶδ’ ὅτι μου πλούτου κενεαὶ χέρες, ἀλλὰ Μένιππε<br>μὴ λέγε πρὸς Χαρίτων τοὐμὸν ὄνειρον ἐμοί.<br>ἀλγέω τὴν διὰ παντὸς ἔπος τόδε πικρὸν ἀκούων·<br>ναὶ φίλε, τῶν παρὰ σοῦ τοῦτ’ ἀνεραστότατον.", "st": "E.32"}, {"sp": "N", "t": "Ἄρτεμι τὶν τόδ’ ἄγαλμα Φιληρατὶς εἵσατο τῆιδε·<br>ἀλλὰ σὺ μὲν δέξαι πότνια, τὴν δὲ σάω.", "st": "E.33"}, {"sp": "N", "t": "τίν με λεοντάγχ’ ὦνα συοκτόνε φήγινον ὄζον<br>θῆκε ‘τίς’; Ἀρχῖνος ‘ποῖος’; ὁ Κρής ‘δέχομαι’.", "st": "E.34"}, {"sp": "N", "t": "Βαττιάδεω παρὰ σῆμα φέρεις πόδας εὖ μὲν ἀοιδήν<br>εἰδότος, εὖ δ’ οἴνωι καίρια συγγελάσαι.", "st": "E.35"}, {"sp": "N", "t": "…", "st": "E.36"}, {"sp": "N", "t": "ὁ Λύκτιος Μενοίτας<br>τὰ τόξα ταῦτ’ ἐπειπών<br>ἔθηκε ‘τῆ, κέρας τοι<br>δίδωμι καὶ φαρέτρην<br>Σάραπι· τοὺς δ’ ὀιστούς<br>ἔχουσιν Ἑσπερῖται’.", "st": "E.37"}, {"sp": "N", "t": "τὰ δῶρα τἀφροδίτηι<br>Σῖμον ἡ περίφοιτος, εἰκόν’ αὑτῆς,<br>ἔθηκε, τήν τε μίτρην<br>† ἡμᾶς τοὺς ἐφίλησε τόν τε πᾶνα<br>† καὶ τοὺς αὐτοὺς ὁρῆι τάλαινα θάρσους.", "st": "E.38"}, {"sp": "N", "t": "Δήμητρι τῆι Πυλαίηι,<br>τῆι τοῦτον οὑκ Πελασγῶν<br>Ἀκρίσιος τὸν νηὸν ἐδείματο, ταῦθ’ ὁ Ναυκρατίτης<br>καὶ τῆι κάτω θυγατρί<br>τὰ δῶρα Τιμόδημος<br>εἵσατο τῶν κερδέων δεκατεύματα· καὶ γὰρ εὔξαθ’ οὕτως.", "st": "E.39"}, {"sp": "N", "t": "Ἱερέη Δήμητρος ἐγώ ποτε καὶ πάλιν Καβείρων,<br>ὦνερ, καὶ μετέπειτα Δινδυμήνης<br>ἡ γρῆυς γενόμην, ἡ νῦν κόνις, ἡ Νο …<br>πολλῶν προστασίη νέων γυναικῶν.<br>καί μοι τέκν’ ἐγένοντο δύ’ ἄρσενα, κἠπέμυσ’ ἐκείνων<br>εὐγήρως ἐνὶ χερσίν· ἕρπε χαίρων.", "st": "E.40"}, {"sp": "N", "t": "ἥμισύ μευ ψυχῆς ἔτι τὸ πνέον, ἥμισυ δ’ οὐκ οἶδ’<br>εἴτ’ Ἔρος εἴτ’ Ἀίδης ἥρπασε, πλὴν ἀφανές.<br>ἦ ῥά τιν’ ἐς παίδων πάλιν ὤιχετο; καὶ μὲν ἀπεῖπον<br>πολλάκι ‘τὴν δρῆστιν μὴ ὑποδέχεσθε νέοι’.<br>† ουκισυνιφησον· ἐκεῖσε γὰρ ἡ λιθόλευστος<br>κείνη καὶ δύσερως οἶδ’ ὅτι που στρέφεται.", "st": "E.41"}, {"sp": "N", "t": "εἰ μὲν ἑκὼν Ἀρχῖν’ ἐπεκώμασα, μυρία μέμφου,<br>εἰ δ’ ἄκων ἥκω, τὴν προπέτειαν ἔα.<br>Ἄκρητος καὶ Ἔρως μ’ ἠνάγκασαν, ὧν ὃ μὲν αὐτῶν<br>εἷλκεν, ὃ δ’ οὐκ εἴα τὴν προπέτειαν ἐᾶν.<br>ἐλθὼν δ’ οὐκ ἐβόησα, τίς ἢ τίνος, ἀλλ’ ἐφίλησα<br>τὴν φλιήν· εἰ τοῦτ’ ἔστ’ ἀδίκημ’, ἀδικέω.", "st": "E.42"}, {"sp": "N", "t": "ἕλκος ἔχων ὁ ξεῖνος ἐλάνθανεν· ὡς ἀνιηρόν<br>πνεῦμα διὰ στηθέων (εἶδες;) ἀνηγάγετο,<br>τὸ τρίτον ἡνίκ’ ἔπινε, τὰ δὲ ῥόδα φυλλοβολεῦντα<br>τὠνδρὸς ἀπὸ στεφάνων πάντ’ ἐγένοντο χαμαί·<br>ὤπτηται μέγα δή τι· μὰ δαίμονας οὐκ ἀπὸ ῥυσμοῦ<br>εἰκάζω, φωρὸς δ’ ἴχνια φὼρ ἔμαθον.", "st": "E.43"}, {"sp": "N", "t": "ἔστι τι ναὶ τὸν Πᾶνα κεκρυμμένον, ἔστι τι ταύτηι<br>ναὶ μὰ Διώνυσον πῦρ ὑπὸ τῆι σποδιῆι·<br>οὐ θαρσέω· μὴ δή με περίπλεκε. πολλάκι λήθει<br>τοῖχον ὑποτρώγων ἡσύχιος ποταμός·<br>τῶι καὶ νῦν δείδοικα, Μενέξενε, μή με παρεισδύς<br>οὗτος † ὁσειγαρνης εἰς τὸν ἔρωτα βάληι.", "st": "E.44"}, {"sp": "N", "t": "…", "st": "E.XLVII"}, {"sp": "N", "t": "‘Ληφθήσει, περίφευγε Μενέκρατες’ εἶπα Πανήμου<br>εἰκάδι, καὶ Λώιου τῆι τίνι; τῆι δεκάτηι<br>ἦλθεν ὁ βοῦς ὑπ’ ἄροτρον ἑκούσιος. εὖ γ’, ἐμὸς Ἑρμῆς,<br>εὖ γ’, ἐμός· οὐ παρὰ τὰς εἴκοσι μεμφόμεθα.", "st": "E.45"}, {"sp": "N", "t": "ὡς ἀγαθὰν Πολύφαμος ἀνεύρετο τὰν ἐπαοιδάν<br>τὠραμένωι· ναὶ Γᾶν, οὐκ ἀμαθὴς ὁ Κύκλωψ·<br>αἱ Μοῦσαι τὸν ἔρωτα κατισχαίνοντι Φίλιππε·<br>ἦ πανακὲς πάντων φάρμακον ἁ σοφία.<br>τοῦτο, δοκέω, χἀ λιμὸς ἔχει μόνον ἐς τὰ πονηρά<br>τὠγαθόν· ἐκκόπτει τὰν φιλόπαιδα νόσον.<br>ἔσθ’ ἁμὶν † χἀκαστὰς ἀφείδεα ποττὸν Ἔρωτα<br>τοῦτ’ εἶπαι ‘κείρευ τὰ πτερὰ παιδάριον,<br>οὐδ’ ὅσον ἀττάραγόν τυ δεδοίκαμες’· αἱ γὰρ ἐπωιδαί<br>οἴκοι τῶ χαλεπῶ τραύματος ἀμφότεραι.", "st": "E.46"}, {"sp": "N", "t": "…", "st": "E.L"}, {"sp": "N", "t": "τὴν ἁλίην Εὔδημος, ἀφ’ ἧς ἅλα λιτὸν ἐπέσθων<br>χειμῶνας μεγάλους ἐξέφυγεν δανέων,<br>θῆκε θεοῖς Σαμόθρηιξι λέγων ὅτι τήνδε κατ’ εὐχήν,<br>ὦ μεγάλοι, σωθεὶς ἐξ ἁλὸς ὧδ’ ἔθετο.", "st": "E.47"}, {"sp": "N", "t": "Εὐμαθίην ἠιτεῖτο διδοὺς ἐμὲ Σῖμος ὁ Μίκκου<br>ταῖς Μούσαις· αἳ δὲ Γλαῦκος ὅκως ἔδοσαν<br>ἀντ’ ὀλίγου μέγα δῶρον. ἐγὼ δ’ ἀνὰ τῆιδε κεχηνώς<br>κεῖμαι τοῦ Σαμίου διπλόον ὁ τραγικός<br>παιδαρίων Διόνυσος ἐπήκοος· οἳ δὲ λέγουσιν<br>‘ἱερὸς ὁ πλόκαμος’ τοὐμὸν ὄνειαρ ἐμοί.", "st": "E.48"}, {"sp": "N", "t": "τῆς Ἀγοράνακτός με λέγε ξένε κωμικὸν ὄντως<br>ἀγκεῖσθαι νίκης μάρτυρα τοῦ Ῥοδίου<br>Πάμφιλον, οὐ μὲν ἔρωτι δεδαγμένον, ἥμισυ δ’ ὀπτῆι<br>ἰσχάδι καὶ λύχνοις Ἴσιδος εἰδόμενον.", "st": "E.49"}, {"sp": "N", "t": "τὴν Φρυγίην Αἴσχρην, ἀγαθὸν γάλα, πᾶσιν ἐν ἐσθλοῖς<br>Μίκκος καὶ ζωὴν οὖσαν ἐγηροκόμει<br>καὶ φθιμένην ἀνέθηκεν, ἐπεσσομένοισιν ὁρᾶσθαι,<br>ἡ γρῆυς μαστῶν ὡς ἀπέχει χάριτας.", "st": "E.50"}, {"sp": "N", "t": "τέσσαρες αἱ Χάριτες, ποτὶ γὰρ μία ταῖς τρισὶ τήναις<br>ἄρτι ποτεπλάσθη κἤτι μύροισι νοτεῖ.<br>εὐαίων ἐν πᾶσιν ἀρίζαλος Βερενίκα,<br>ἇς ἄτερ οὐδ’ αὐταὶ ταὶ Χάριτες Χάριτες.", "st": "E.51"}, {"sp": "N", "t": "τὸν τὸ καλὸν μελανεῦντα Θεόκριτον, εἰ μὲν ἔμ’ ἔχθει,<br>τετράκι μισοίης, εἰ δὲ φιλεῖ, φιλέοις·<br>ναιχὶ πρὸς εὐχαίτεω Γανυμήδεος, οὐράνιε Ζεῦ·<br>καὶ σύ ποτ’ ἠράσθης — οὐκέτι μακρὰ λέγω.", "st": "E.52"}, {"sp": "N", "t": "καὶ πάλιν Εἰλήθυια Λυκαινίδος ἐλθὲ καλεύσης<br>εὔλοχος ὠδίνων ὧδε σὺν εὐτοκίηι,<br>ὡς τόδε νῦν μέν, ἄνασσα, κόρης ὕπερ, ἀντὶ δὲ παιδός<br>ὕστερον εὐώδης ἄλλο τι νηὸς ἔχοι.", "st": "E.53"}, {"sp": "N", "t": "τὸ χρέος ὡς ἀπέχεις Ἀσκλήπιε, τὸ πρὸ γυναικός<br>Δημοδίκης Ἀκέσων ὤφελεν εὐξάμενος,<br>γινώσκειν, ἤν δ’ ἆρα λάθηι καί † μιν ἀπαιτῆις,<br>φησὶ παρέξεσθαι μαρτυρίην ὁ πίναξ.", "st": "E.54"}, {"sp": "N", "t": "τῶι με Κανωπίται Καλλίστιον εἴκοσι μύξαις<br>πλούσιον ἁ Κριτίου λύχνον ἔθηκε θεῶι<br>εὐξαμένα περὶ παιδὸς Ἀπελλίδος· ἐς δ’ ἐμὰ φέγγη<br>ἀθρήσας φάσεις ‘Ἕσπερε πῶς ἔπεσες’.", "st": "E.55"}, {"sp": "N", "t": "φησὶν ὅ με στήσας Εὐαίνετος (οὐ γὰρ ἔγωγε<br>γινώσκω) νίκης ἀντί με τῆς ἰδίης<br>ἀγκεῖσθαι χάλκειον ἀλέκτορα Τυνδαρίδηισι·<br>πιστεύω Φαίδρου παιδὶ Φιλοξενίδεω.", "st": "E.56"}, {"sp": "N", "t": "Ἰναχίης ἕστηκεν ἐν Ἴσιδος ἡ Θάλεω παῖς<br>Αἰσχυλὶς Εἰρήνης μητρὸς ὑποσχεσίηι.", "st": "E.57"}, {"sp": "N", "t": "τίς, ξένος ὦ ναυηγέ; Λεόντιχος ἐνθάδε νεκρόν<br>εὗρέ σ’ ἐπ’ αἰγιαλοῦ χῶσέ τε τῶιδε τάφωι<br>δακρύσας ἐπίκηρον ἑὸν βίον· οὐδὲ γὰρ αὐτός<br>ἥσυχον, αἰθυίηι δ’ ἶσα θαλασσοπορεῖ.", "st": "E.58"}, {"sp": "N", "t": "εὐδαίμων ὅτι τἄλλα μανεὶς ὡρχαῖος Ὀρέστας,<br>† λευκαρετανμαν οὐκ ἐμάνη μανίαν<br>οὐδ’ ἔλαβ’ ἐξέτασιν τῶ Φωκέος ἅτις ἐλέγχει<br>τὸν φίλον, † ἀλλαιχ’ ἓν δρᾶμ’ ἐδίδαξε μόνον·<br>ἦ τάχα κα τὸν ἑταῖρον ἀπώλεσε τοῦτο ποήσας —<br>κἠγὼ τὼς πολλὼς οὐκέτ’ ἔχω Πυλάδας.", "st": "E.59"}, {"sp": "N", "t": "οἵτινες Ἀλείοιο παρέρπετε σῆμα Κίμωνος,<br>ἴστε τὸν Ἱππαίου παῖδα παρερχόμενοι.", "st": "E.60"}, {"sp": "N", "t": "Αἴνιε, καὶ σὺ γὰρ ὧδε, Μενέκρατες, οὐκ ἐπὶ πουλύ<br>ἦσθα· τί σε, ξείνων λῶιστε, κατειργάσατο;<br>ἦ ῥα τὸ καὶ Κένταυρον; ‘ὅ μοι πεπρωμένος ὕπνος<br>ἦλθεν, ὁ δὲ τλήμων οἶνος ἔχει πρόφασιν’.", "st": "E.61"}, {"sp": "N", "t": "…", "st": "E.LXVI"}, {"sp": "N", "t": "…", "st": "E.LXVII"}, {"sp": "N", "t": "…", "st": "E.LXVIII"}, {"sp": "N", "t": "…", "st": "E.LXIX"}, {"sp": "N", "t": "…", "st": "E.LXX"}, {"sp": "N", "t": "…", "st": "E.LXXI"}, {"sp": "N", "t": "…", "st": "E.LXXII"}, {"sp": "N", "t": "Κυνθιάδες θαρσεῖτε, τὰ γὰρ τοῦ Κρητὸς Ἐχέμμα<br>κεῖται ἐν Ὀρτυγίηι τόξα παρ’ Ἀρτέμιδι,<br>οἷς ὑμέων ἐκένωσεν ὄρος μέγα· νῦν δὲ πέπαυται,<br>αἶγες, ἐπεὶ σπονδὰς ἡ θεὸς εἰργάσατο.", "st": "E.62"}, {"sp": "N", "t": "οὕτως ὑπνώσαις Κωνώπιον, ὡς ἐμὲ ποιεῖς<br>κοιμᾶσθαι ψυχροῖς τοῖσδε παρὰ προθύροις.<br>οὕτως ὑπνώσαις ἀδικωτάτη, ὡς τὸν ἐραστήν<br>κοιμίζεις, ἐλέου δ’ οὐδ’ ὄναρ ἠντίασας.<br>γείτονες οἰκτείρουσι, σὺ δ’ οὐδ’ ὄναρ. ἡ πολιὴ δέ<br>αὐτίκ’ ἀναμνήσει ταῦτά σε πάντα κόμη.", "st": "E.63"}], []);})();
